// Teoribok: MEK1300, MEK3100, NUM, MEK2200, OKON, PROD, STKD6610, MATS1500, KJEMI
// ---------------- MEK1300: Programmering med Python ----------------
TOPICS("MEK1300", 0, [
{ id: "tall-og-typer",
  nb: { t: "Tall og typer",
    intro: "Python har flere tallslag. `int` er heltall, `float` er desimaltall. Vanlig divisjon `/` gir alltid `float`, mens `//` runder ned til et heltall og `%` gir resten. `type(x)` viser hvilken type en verdi har.",
    f: [["a\\,/\\,b", "vanlig divisjon, gir alltid float"], ["a\\,/\\!/\\,b", "heltallsdivisjon, rundes ned"], ["a \\% b", "resten etter heltallsdivisjon"]],
    legend: [["a,\\ b", "tallene som divideres", ""]],
    ex: "`7 // 2` gir `3`, og `7 % 2` gir `1`, siden $7 = 3\\cdot 2 + 1$.\n`7 / 2` gir 3,5 (float).",
    tip: "`//` og `%` henger sammen: `a == (a // b) * b + a % b`." },
  en: { t: "Numbers and types",
    intro: "Python has several kinds of numbers. `int` is a whole number, `float` a decimal number. Regular division `/` always gives a `float`, while `//` rounds down to an integer and `%` gives the remainder. `type(x)` shows a value's type.",
    f: [["a\\,/\\,b", "regular division, always float"], ["a\\,/\\!/\\,b", "integer division, rounded down"], ["a \\% b", "remainder after integer division"]],
    legend: [["a,\\ b", "the numbers being divided", ""]],
    ex: "`7 // 2` gives `3`, and `7 % 2` gives `1`, since $7 = 3\\cdot 2 + 1$.\n`7 / 2` gives `3.5`.",
    tip: "`//` and `%` are linked: `a == (a // b) * b + a % b`." } },
{ id: "strenger-og-indeksering",
  nb: { t: "Strenger og indeksering",
    intro: "En streng er en sekvens av tegn. Hvert tegn har en indeks som starter på 0, og negative indekser teller bakfra fra $-1$. Med utsnitt `s[i:j]` henter du tegnene fra indeks $i$ til og med $j-1$.",
    f: [["s[i]", "tegnet på indeks $i$"], ["s[i:j]", "utsnitt fra $i$ til og med $j-1$"], ["s[-1]", "siste tegn"]],
    legend: [["s", "en streng (eller liste)", ""], ["i,\\ j", "start- og sluttindeks", ""]],
    ex: "`s = \"robotikk\"`\n`s[2:6]` gir `\"boti\"` (indeks 2, 3, 4, 5).\n`s[-1]` gir `\"k\"`.",
    tip: "Lengden på `s[i:j]` er $j - i$ — den siste indeksen er aldri med." },
  en: { t: "Strings and indexing",
    intro: "A string is a sequence of characters. Each character has an index starting at 0, and negative indices count backwards from $-1$. A slice `s[i:j]` gets the characters from index $i$ up to and including $j-1$.",
    f: [["s[i]", "the character at index $i$"], ["s[i:j]", "slice from $i$ up to and including $j-1$"], ["s[-1]", "the last character"]],
    legend: [["s", "a string (or list)", ""], ["i,\\ j", "start and end index", ""]],
    ex: "`s = \"robotikk\"`\n`s[2:6]` gives `\"boti\"` (indices 2, 3, 4, 5).\n`s[-1]` gives `\"k\"`.",
    tip: "The length of `s[i:j]` is $j - i$ — the last index is never included." } },
{ id: "lister",
  nb: { t: "Lister",
    intro: "En liste `[1, 2, 3]` er en ordnet, endringsbar samling av verdier. Du kan legge til med `append`, hente lengden med `len`, og hente ut deler med utsnitt akkurat som for strenger. En tuppel `(1, 2)` ligner, men kan ikke endres etter at den er laget.",
    f: [["\\text{len}(x)", "antall elementer i lista"], ["x.\\text{append}(v)", "legger $v$ til på slutten"]],
    legend: [["x", "en liste", ""], ["v", "verdien som legges til", ""]],
    ex: "`x = [1, 2, 3]`\n`x.append(4)` gjør `x` til `[1, 2, 3, 4]`, og `len(x)` blir `4`.",
    tip: "Lister sendes til funksjoner som referanse: endrer funksjonen lista, ser du endringen også utenfor." },
  en: { t: "Lists",
    intro: "A list `[1, 2, 3]` is an ordered, mutable collection of values. You can add to it with `append`, get its length with `len`, and slice it just like strings. A tuple `(1, 2)` is similar but cannot be changed after it is created.",
    f: [["\\text{len}(x)", "number of elements in the list"], ["x.\\text{append}(v)", "adds $v$ to the end"]],
    legend: [["x", "a list", ""], ["v", "the value being added", ""]],
    ex: "`x = [1, 2, 3]`\n`x.append(4)` makes `x` `[1, 2, 3, 4]`, and `len(x)` becomes `4`.",
    tip: "Lists are passed to functions by reference: if the function changes the list, you see the change outside too." } },
{ id: "fstrenger",
  nb: { t: "f-strenger og format",
    intro: "En f-streng, skrevet `f\"...\"`, setter verdier rett inn i tekst med krøllparenteser. Etter et kolon kan du gi et formatspesifikasjon, som `.2f` for to desimaler. Dette gjør utskrift ryddig og lesbar.",
    f: [["f\"\\{x\\}\"", "setter inn verdien av $x$"], ["f\"\\{x:.2f\\}\"", "$x$ med 2 desimaler"]],
    legend: [["x", "verdien som settes inn", ""]],
    ex: "`x` er satt til pi med mange desimaler.\n`f\"{x:.2f}\"` gir teksten 3,14.",
    tip: "`.2f` runder til to desimaler, det klipper dem ikke bare av." },
  en: { t: "f-strings and formatting",
    intro: "An f-string, written `f\"...\"`, inserts values directly into text using curly braces. After a colon you can give a format spec, such as `.2f` for two decimals. This keeps printed output tidy and readable.",
    f: [["f\"\\{x\\}\"", "inserts the value of $x$"], ["f\"\\{x:.2f\\}\"", "$x$ with 2 decimals"]],
    legend: [["x", "the value being inserted", ""]],
    ex: "`x = 3.14159`\n`f\"{x:.2f}\"` gives `\"3.14\"`.",
    tip: "`.2f` rounds to two decimals, it does not just truncate them." } }
]);
TOPICS("MEK1300", 1, [
{ id: "for-og-range",
  nb: { t: "for-løkke og range",
    intro: "En `for`-løkke gjentar kode for hvert element i en sekvens, ofte laget med `range(start, stopp, steg)`. Stoppverdien er aldri med selv. Uten start og steg begynner `range` på 0 og teller opp med 1.",
    f: [["\\text{range}(a, b, s)", "tallene $a, a{+}s, a{+}2s, \\ldots$ opp til, men ikke med, $b$"]],
    legend: [["a", "startverdi (inkludert)", ""], ["b", "stoppverdi (ikke inkludert)", ""], ["s", "steg", ""]],
    ex: "`for i in range(2, 8, 2): print(i)`\nskriver ut `2 4 6` — 8 er ikke med.",
    tip: "Antall gjennomkjøringer i `range(a, b, s)` er $\\lceil (b-a)/s \\rceil$." },
  en: { t: "for loop and range",
    intro: "A `for` loop repeats code for each element in a sequence, often built with `range(start, stop, step)`. The stop value is never included itself. Without start and step, `range` begins at 0 and counts up by 1.",
    f: [["\\text{range}(a, b, s)", "the numbers $a, a{+}s, a{+}2s, \\ldots$ up to but not including $b$"]],
    legend: [["a", "start value (included)", ""], ["b", "stop value (not included)", ""], ["s", "step", ""]],
    ex: "`for i in range(2, 8, 2): print(i)`\nprints `2 4 6` — 8 is not included.",
    tip: "The number of iterations of `range(a, b, s)` is $\\lceil (b-a)/s \\rceil$." } },
{ id: "while-lokke",
  nb: { t: "while-løkke",
    intro: "En `while`-løkke gjentar kode så lenge en betingelse er sann. Betingelsen sjekkes før hver runde, så den kan kjøre null ganger. Glemmer du å endre variabelen som testes, blir løkka uendelig.",
    f: [["\\text{while } P:", "kjør blokka så lenge utsagnet $P$ er sant"]],
    legend: [["P", "en betingelse (sann/usann)", ""]],
    ex: "`n = 0`\n`while n < 10: n += 3`\nEtter løkka er `n = 12` (0, 3, 6, 9, 12 — 4 runder).",
    tip: "Sjekk alltid at noe i betingelsen faktisk endres inne i løkka." },
  en: { t: "while loop",
    intro: "A `while` loop repeats code as long as a condition is true. The condition is checked before each round, so it can run zero times. If you forget to change the tested variable, the loop runs forever.",
    f: [["\\text{while } P:", "run the block as long as the statement $P$ is true"]],
    legend: [["P", "a condition (true/false)", ""]],
    ex: "`n = 0`\n`while n < 10: n += 3`\nAfter the loop, `n = 12` (0, 3, 6, 9, 12 — 4 rounds).",
    tip: "Always check that something in the condition is actually changed inside the loop." } },
{ id: "betingelser",
  nb: { t: "Betingelser: if/elif/else",
    intro: "`if`, `elif` og `else` lar programmet velge mellom grener ut fra betingelser. Python sjekker grenene i rekkefølge og kjører bare den første som er sann. Sammenkjedede sammenligninger som `5 < x < 10` fungerer direkte.",
    f: [["\\text{if } P_1: \\ldots \\text{elif } P_2: \\ldots \\text{else}: \\ldots", "første sanne $P_i$ avgjør hvilken gren som kjører"]],
    legend: [["P_1,\\ P_2", "betingelser sjekket i rekkefølge", ""]],
    ex: "`x = 18`\n`if x < 4: ... elif x < 7: ... else: print(\"C\")`\nSiden $18 \\not< 4$ og $18 \\not< 7$, skrives `\"C\"`.",
    tip: "`elif` sjekkes bare hvis alle tidligere betingelser var usanne — rekkefølgen betyr noe." },
  en: { t: "Conditionals: if/elif/else",
    intro: "`if`, `elif` and `else` let the program choose between branches based on conditions. Python checks the branches in order and runs only the first one that is true. Chained comparisons like `5 < x < 10` work directly.",
    f: [["\\text{if } P_1: \\ldots \\text{elif } P_2: \\ldots \\text{else}: \\ldots", "the first true $P_i$ decides which branch runs"]],
    legend: [["P_1,\\ P_2", "conditions checked in order", ""]],
    ex: "`x = 18`\n`if x < 4: ... elif x < 7: ... else: print(\"C\")`\nSince $18 \\not< 4$ and $18 \\not< 7$, `\"C\"` is printed.",
    tip: "`elif` is only checked if all earlier conditions were false — order matters." } },
{ id: "break-continue",
  nb: { t: "break og continue",
    intro: "`break` avslutter løkka umiddelbart, mens `continue` bare hopper til neste runde og fortsetter løkka. Begge brukes gjerne sammen med en `if`-betingelse inne i løkka for å håndtere spesialtilfeller.",
    f: [["\\text{break}", "avslutter hele løkka med en gang"], ["\\text{continue}", "hopper over resten av runden, fortsetter løkka"]],
    legend: [],
    ex: "`for i in range(3): pass`\n`print(i)` skriver `2`, siden løkkevariabelen beholder siste verdi etter løkka.",
    tip: "`break` går ut av løkka, `continue` blir værende i den — ikke forveksle dem." },
  en: { t: "break and continue",
    intro: "`break` ends the loop immediately, while `continue` just skips to the next round and keeps the loop going. Both are typically used with an `if` condition inside the loop to handle special cases.",
    f: [["\\text{break}", "ends the whole loop immediately"], ["\\text{continue}", "skips the rest of the round, loop continues"]],
    legend: [],
    ex: "`for i in range(3): pass`\n`print(i)` prints `2`, since the loop variable keeps its last value after the loop.",
    tip: "`break` leaves the loop, `continue` stays in it — do not mix them up." } },
{ id: "listeforstaelse",
  nb: { t: "Listeforståelse",
    intro: "En listeforståelse bygger en ny liste kompakt i én linje: `[uttrykk for x in sekvens]`. Du kan legge til en `if` på slutten for å filtrere hvilke elementer som tas med.",
    f: [["[e(x) \\text{ for } x \\text{ in } s]", "ny liste av $e(x)$ for hver $x$ i $s$"], ["[e(x) \\text{ for } x \\text{ in } s \\text{ if } P(x)]", "bare de $x$ der $P(x)$ er sann"]],
    legend: [["e(x)", "uttrykket som beregnes for hver $x$", ""], ["s", "sekvensen som løkkes over", ""], ["P(x)", "filterbetingelse", ""]],
    ex: "`[i**2 for i in range(4)]` gir `[0, 1, 4, 9]`.\n`[i for i in range(11) if i % 3 == 0]` gir 4 tall: `[0, 3, 6, 9]`.",
    tip: "Les listeforståelsen som en vanlig `for`-løkke skrevet baklengs: verdi først, så `for`, så ev. `if`." },
  en: { t: "List comprehension",
    intro: "A list comprehension builds a new list compactly in one line: `[expression for x in sequence]`. You can add an `if` at the end to filter which elements are included.",
    f: [["[e(x) \\text{ for } x \\text{ in } s]", "new list of $e(x)$ for each $x$ in $s$"], ["[e(x) \\text{ for } x \\text{ in } s \\text{ if } P(x)]", "only the $x$ where $P(x)$ is true"]],
    legend: [["e(x)", "the expression computed for each $x$", ""], ["s", "the sequence looped over", ""], ["P(x)", "filter condition", ""]],
    ex: "`[i**2 for i in range(4)]` gives `[0, 1, 4, 9]`.\n`[i for i in range(11) if i % 3 == 0]` gives 4 numbers: `[0, 3, 6, 9]`.",
    tip: "Read a list comprehension as an ordinary `for` loop written backwards: value first, then `for`, then optional `if`." } }
]);
// ---------------- MEK3100: Videregående programmering ----------------
TOPICS("MEK3100", 0, [
{ id: "klasser-og-init",
  nb: { t: "Klasser og __init__",
    intro: "En klasse er en mal for å lage objekter. `__init__` er konstruktøren: den kjører automatisk når du lager et nytt objekt, og setter opp attributtene. `self` inne i en metode refererer til objektet metoden kalles på.",
    f: [["\\text{class } K: \\ \\text{def }\\_\\_\\text{init}\\_\\_(\\text{self}, \\ldots)", "konstruktøren, kjøres ved $K(\\ldots)$"], ["\\text{obj.metode}() \\equiv K.\\text{metode}(\\text{obj})", "objektet sendes automatisk som `self`"]],
    legend: [["self", "objektet (instansen) selv", ""]],
    ex: "`class Rektangel:`\n`    def __init__(self, b, h): self.b, self.h = b, h`\n`    def areal(self): return self.b * self.h`\n`Rektangel(8, 4).areal()` gir 32.",
    tip: "`self` er bare et navn, men følg konvensjonen — Python fyller det inn automatisk uansett hva du kaller det." },
  en: { t: "Classes and __init__",
    intro: "A class is a template for creating objects. `__init__` is the constructor: it runs automatically when you create a new object, and sets up the attributes. `self` inside a method refers to the object the method is called on.",
    f: [["\\text{class } K: \\ \\text{def }\\_\\_\\text{init}\\_\\_(\\text{self}, \\ldots)", "the constructor, runs on $K(\\ldots)$"], ["\\text{obj.method}() \\equiv K.\\text{method}(\\text{obj})", "the object is passed automatically as `self`"]],
    legend: [["self", "the object (instance) itself", ""]],
    ex: "`class Rektangel:`\n`    def __init__(self, b, h): self.b, self.h = b, h`\n`    def areal(self): return self.b * self.h`\n`Rektangel(8, 4).areal()` gives 32.",
    tip: "`self` is just a name, but follow the convention — Python fills it in automatically regardless of what you call it." } },
{ id: "arv-og-super",
  nb: { t: "Arv og super()",
    intro: "En klasse kan arve fra en annen: `class Hund(Dyr):` gjør `Hund` til en underklasse av `Dyr` og gir den tilgang til foreldreklassens metoder. `super().__init__()` kaller foreldrens konstruktør, slik at attributtene derfra settes opp riktig.",
    f: [["\\text{class } B(A):", "$B$ arver alle metoder og attributter fra $A$"], ["\\text{super}().\\_\\_\\text{init}\\_\\_(\\ldots)", "kaller konstruktøren til foreldreklassen $A$"]],
    legend: [["A", "foreldreklassen (superklassen)", ""], ["B", "underklassen", ""]],
    ex: "`class Hund(Dyr):`\n`    def __init__(self, navn): super().__init__(navn)`\nAlle attributter fra `Dyr` settes opp automatisk.",
    tip: "Glemmer du `super().__init__()`, mangler underklassen attributtene fra foreldreklassen." },
  en: { t: "Inheritance and super()",
    intro: "A class can inherit from another: `class Hund(Dyr):` makes `Hund` a subclass of `Dyr` and gives it access to the parent class's methods. `super().__init__()` calls the parent's constructor, so the attributes from there are set up correctly.",
    f: [["\\text{class } B(A):", "$B$ inherits all methods and attributes from $A$"], ["\\text{super}().\\_\\_\\text{init}\\_\\_(\\ldots)", "calls the constructor of the parent class $A$"]],
    legend: [["A", "the parent class (superclass)", ""], ["B", "the subclass", ""]],
    ex: "`class Hund(Dyr):`\n`    def __init__(self, navn): super().__init__(navn)`\nAll attributes from `Dyr` are set up automatically.",
    tip: "Forget `super().__init__()` and the subclass will be missing the attributes from the parent class." } },
{ id: "innkapsling-polymorfi",
  nb: { t: "Innkapsling og polymorfi",
    intro: "Innkapsling betyr å skjule intern tilstand bak et kontrollert grensesnitt; i Python markeres interne attributter gjerne med et understrek foran navnet, som `_verdi`. Polymorfi betyr at ulike klasser kan ha en metode med samme navn, men ulik oppførsel.",
    f: [["\\_\\text{navn}", "konvensjon for «internt» attributt"], ["\\text{areal}_{\\text{Sirkel}} \\neq \\text{areal}_{\\text{Rektangel}}", "samme metodenavn, ulik implementasjon"]],
    legend: [],
    ex: "`Sirkel.areal()` og `Rektangel.areal()` bruker begge navnet `areal`, men regner det ut helt forskjellig.",
    tip: "Polymorfi lar deg kalle `.areal()` på en liste av ulike former uten å sjekke typen først." },
  en: { t: "Encapsulation and polymorphism",
    intro: "Encapsulation means hiding internal state behind a controlled interface; in Python, internal attributes are often marked with a leading underscore, as in `_value`. Polymorphism means different classes can have a method with the same name but different behaviour.",
    f: [["\\_\\text{name}", "convention for an internal attribute"], ["\\text{area}_{\\text{Circle}} \\neq \\text{area}_{\\text{Rectangle}}", "same method name, different implementation"]],
    legend: [],
    ex: "`Sirkel.areal()` and `Rektangel.areal()` both use the name `areal`, but compute it completely differently.",
    tip: "Polymorphism lets you call `.areal()` on a list of different shapes without checking the type first." } },
{ id: "property",
  nb: { t: "@property",
    intro: "`@property` gjør en metode om til noe som kan leses som et vanlig attributt, uten parenteser. Det er nyttig når en verdi skal beregnes fra andre attributter, men brukes akkurat som om den var lagret direkte.",
    f: [["@\\text{property}", "gjør at `obj.metode` leses uten `()`"]],
    legend: [],
    ex: "`class Sirkel:`\n`    @property`\n`    def areal(self): return pi * self.r**2`\n`Sirkel(2).areal` (uten parentes) gir arealet.",
    tip: "Bruk `@property` for beregnede verdier — det holder grensesnittet enkelt selv om utregningen endres senere." },
  en: { t: "@property",
    intro: "`@property` turns a method into something that can be read like a plain attribute, without parentheses. It is useful when a value should be computed from other attributes, but used exactly as if it were stored directly.",
    f: [["@\\text{property}", "makes `obj.method` readable without `()`"]],
    legend: [],
    ex: "`class Sirkel:`\n`    @property`\n`    def areal(self): return 3.14 * self.r**2`\n`Sirkel(2).areal` (no parentheses) gives the area.",
    tip: "Use `@property` for computed values — it keeps the interface simple even if the calculation changes later." } }
]);
TOPICS("MEK3100", 1, [
{ id: "kompleksitet",
  nb: { t: "Tidskompleksitet, O-notasjon",
    intro: "O-notasjon beskriver hvordan kjøretiden til en algoritme vokser med antall elementer $n$, for store $n$. $O(1)$ er konstant, $O(\\log n)$ vokser sakte, $O(n)$ lineært og $O(n^2)$ kvadratisk. Det er dette som avgjør om en algoritme takler store datamengder.",
    f: [["O(1) < O(\\log n) < O(n) < O(n\\log n) < O(n^2)", "vanlig rekkefølge, fra raskest til tregest"]],
    legend: [["n", "antall elementer", ""]],
    ex: "Oppslag i en `dict` er $O(1)$: nesten uavhengig av størrelsen.\nBinærsøk i en sortert liste er $O(\\log n)$: søkeområdet halveres hvert steg.",
    tip: "Dobler du $n$ i en $O(n^2)$-algoritme, firedobles kjøretiden — ikke bare dobles." },
  en: { t: "Time complexity, O-notation",
    intro: "O-notation describes how an algorithm's running time grows with the number of elements $n$, for large $n$. $O(1)$ is constant, $O(\\log n)$ grows slowly, $O(n)$ linearly and $O(n^2)$ quadratically. This is what determines whether an algorithm can handle large amounts of data.",
    f: [["O(1) < O(\\log n) < O(n) < O(n\\log n) < O(n^2)", "typical order, fastest to slowest"]],
    legend: [["n", "number of elements", ""]],
    ex: "Lookup in a `dict` is $O(1)$: almost independent of size.\nBinary search in a sorted list is $O(\\log n)$: the search space halves each step.",
    tip: "Doubling $n$ in an $O(n^2)$ algorithm quadruples the running time — not just doubles it." } },
{ id: "rekursjon",
  nb: { t: "Rekursjon",
    intro: "En rekursiv funksjon kaller seg selv med et mindre problem, og trenger et basistilfelle som stopper kjedet av kall. Uten basistilfelle ender funksjonen i `RecursionError` fordi kallene aldri tar slutt.",
    f: [["f(n) = n\\cdot f(n-1),\\ \\ f(1) = 1", "fakultet: rekursivt trinn og basistilfelle"]],
    legend: [["n", "problemstørrelsen", ""]],
    ex: "`def fak(n):`\n`    if n <= 1: return 1`\n`    return n * fak(n - 1)`\n`fak(3)` gir $3\\cdot 2\\cdot 1 = 6$.",
    tip: "Skriv alltid basistilfellet først — det er det som garanterer at rekursjonen faktisk stopper." },
  en: { t: "Recursion",
    intro: "A recursive function calls itself on a smaller problem, and needs a base case to stop the chain of calls. Without a base case, the function ends in a `RecursionError` because the calls never stop.",
    f: [["f(n) = n\\cdot f(n-1),\\ \\ f(1) = 1", "factorial: recursive step and base case"]],
    legend: [["n", "the problem size", ""]],
    ex: "`def fak(n):`\n`    if n <= 1: return 1`\n`    return n * fak(n - 1)`\n`fak(3)` gives $3\\cdot 2\\cdot 1 = 6$.",
    tip: "Always write the base case first — it is what guarantees the recursion actually stops." } },
{ id: "stakk-og-ko",
  nb: { t: "Stakk og kø",
    intro: "En stakk (stack) følger LIFO: sist inn, først ut, som en bunke tallerkener. En kø (queue) følger FIFO: først inn, først ut. En Python-liste kan brukes som stakk med `append`/`pop`, mens `collections.deque` egner seg bedre som kø.",
    f: [["\\text{Stakk: LIFO}", "`append`/`pop` i samme ende"], ["\\text{Kø: FIFO}", "legg til i den ene enden, ta ut i den andre"]],
    legend: [],
    ex: "`s = []`; `s.append(1)`; `s.append(5)`; `s.pop()`\n`s.append(4)`; `s.pop()`; `s.append(9)`\nNå er `s = [1, 9]`.",
    tip: "`.pop()` uten argument fjerner alltid det siste elementet — det er dette som gjør lista til en stakk." },
  en: { t: "Stack and queue",
    intro: "A stack follows LIFO: last in, first out, like a pile of plates. A queue follows FIFO: first in, first out. A Python list can be used as a stack with `append`/`pop`, while `collections.deque` is better suited as a queue.",
    f: [["\\text{Stack: LIFO}", "`append`/`pop` at the same end"], ["\\text{Queue: FIFO}", "add at one end, remove at the other"]],
    legend: [],
    ex: "`s = []`; `s.append(1)`; `s.append(5)`; `s.pop()`\n`s.append(4)`; `s.pop()`; `s.append(9)`\nNow `s = [1, 9]`.",
    tip: "`.pop()` with no argument always removes the last element — that is what makes the list a stack." } },
{ id: "sortering-sok",
  nb: { t: "Sortering og søk",
    intro: "Sammenligningsbasert sortering kan i beste fall gjøres i $O(n\\log n)$, som Pythons innebygde Timsort klarer. Er lista allerede sortert, gir binærsøk et raskt oppslag ved gjentatte ganger å halvere søkeområdet.",
    f: [["O(n\\log n)", "beste mulige kompleksitet for sammenligningsbasert sortering"], ["O(\\log n)", "binærsøk i en sortert liste"]],
    legend: [["n", "antall elementer", ""]],
    ex: "Binærsøk i en sortert liste med 4095 elementer trenger høyst $\\lceil\\log_2(4096)\\rceil = 12$ sammenligninger.",
    tip: "Binærsøk krever at lista er sortert på forhånd — ellers gir den feil svar uten å varsle om det." },
  en: { t: "Sorting and search",
    intro: "Comparison-based sorting can at best be done in $O(n\\log n)$, which Python's built-in Timsort achieves. If a list is already sorted, binary search gives fast lookup by repeatedly halving the search space.",
    f: [["O(n\\log n)", "best possible complexity for comparison-based sorting"], ["O(\\log n)", "binary search in a sorted list"]],
    legend: [["n", "number of elements", ""]],
    ex: "Binary search in a sorted list of 4095 elements needs at most $\\lceil\\log_2(4096)\\rceil = 12$ comparisons.",
    tip: "Binary search requires the list to be sorted beforehand — otherwise it gives a wrong answer without warning." } }
]);
TOPICS("MEK3100", 2, [
{ id: "numpy-array",
  nb: { t: "NumPy-array og vektorisering",
    intro: "Et NumPy-array ligner en liste, men regneoperasjoner virker elementvis på hele arrayet uten en eksplisitt løkke. Dette kalles vektorisering og er ofte 10–100 ganger raskere enn en Python-løkke over en vanlig liste.",
    f: [["a * c", "hvert element i $a$ multipliseres med $c$"], ["a + b", "elementvis addisjon av like store arrays"]],
    legend: [["a,\\ b", "NumPy-arrays", ""], ["c", "en skalar", ""]],
    ex: "`a = np.array([1, 2, 3])`\n`a * 2` gir `[2 4 6]` — elementvis, ikke gjentakelse som for en liste.",
    tip: "`liste * 2` gjentar en vanlig Python-liste, mens `array * 2` ganger hvert tall — ikke bland dem." },
  en: { t: "NumPy array and vectorization",
    intro: "A NumPy array looks like a list, but arithmetic operations act elementwise on the whole array without an explicit loop. This is called vectorization and is often 10–100 times faster than a Python loop over a plain list.",
    f: [["a * c", "each element of $a$ multiplied by $c$"], ["a + b", "elementwise addition of equal-sized arrays"]],
    legend: [["a,\\ b", "NumPy arrays", ""], ["c", "a scalar", ""]],
    ex: "`a = np.array([1, 2, 3])`\n`a * 2` gives `[2 4 6]` — elementwise, not repetition as for a list.",
    tip: "`list * 2` repeats a plain Python list, while `array * 2` multiplies each number — do not mix them up." } },
{ id: "linspace-arange",
  nb: { t: "linspace og arange",
    intro: "`np.linspace(a, b, n)` gir $n$ jevnt fordelte punkter fra $a$ til og med $b$ — begge endepunktene er med. `np.arange(a, b, s)` fungerer som `range`, men returnerer et array og tar også desimaltall som steg.",
    f: [["\\text{linspace}(a, b, n)", "avstand mellom punktene: $(b-a)/(n-1)$"]],
    legend: [["a,\\ b", "start- og sluttverdi", ""], ["n", "antall punkter", ""]],
    ex: "`np.linspace(0, 1, 5)` gir fem punkter mellom 0 og 1, avstand $1/4 = 0{,}25$.",
    tip: "`linspace` tar antall punkter, `arange` tar steglengden — lett å forveksle." },
  en: { t: "linspace and arange",
    intro: "`np.linspace(a, b, n)` gives $n$ evenly spaced points from $a$ up to and including $b$ — both endpoints are included. `np.arange(a, b, s)` works like `range`, but returns an array and also accepts decimal steps.",
    f: [["\\text{linspace}(a, b, n)", "spacing between points: $(b-a)/(n-1)$"]],
    legend: [["a,\\ b", "start and end value", ""], ["n", "number of points", ""]],
    ex: "`np.linspace(0, 1, 5)` gives `[0, 0.25, 0.5, 0.75, 1]`, spacing $1/4 = 0.25$.",
    tip: "`linspace` takes the number of points, `arange` takes the step size — easy to mix up." } },
{ id: "matrisemultiplikasjon",
  nb: { t: "Matriseoperasjoner",
    intro: "`A * B` mellom to NumPy-arrays er elementvis multiplikasjon, mens `np.dot(A, B)` eller `A @ B` er ordentlig matrisemultiplikasjon. `reshape` endrer formen på et array uten å endre dataene, og `-1` lar NumPy regne ut den siste dimensjonen selv.",
    f: [["A \\,@\\, B", "matrisemultiplikasjon"], ["A * B", "elementvis multiplikasjon (krever samme form)"]],
    legend: [["A,\\ B", "matriser (2D NumPy-arrays)", ""]],
    ex: "`np.arange(12).reshape(4, -1).shape` gir `(4, 3)`, siden $12/4 = 3$.",
    tip: "`A * B` og `A @ B` gir svært ulikt resultat — velg `@` når du mener matrisemultiplikasjon." },
  en: { t: "Matrix operations",
    intro: "`A * B` between two NumPy arrays is elementwise multiplication, while `np.dot(A, B)` or `A @ B` is true matrix multiplication. `reshape` changes an array's shape without changing the data, and `-1` lets NumPy work out the last dimension itself.",
    f: [["A \\,@\\, B", "matrix multiplication"], ["A * B", "elementwise multiplication (requires the same shape)"]],
    legend: [["A,\\ B", "matrices (2D NumPy arrays)", ""]],
    ex: "`np.arange(12).reshape(4, -1).shape` gives `(4, 3)`, since $12/4 = 3$.",
    tip: "`A * B` and `A @ B` give very different results — use `@` when you mean matrix multiplication." } },
{ id: "unntakshandtering",
  nb: { t: "try / except",
    intro: "`try`/`except` fanger og håndterer feil (unntak) som oppstår mens programmet kjører, i stedet for at hele programmet krasjer. `except ValueError:` fanger bare den bestemte feiltypen, slik at andre feil fortsatt slipper gjennom.",
    f: [["\\text{try}: \\ldots \\text{except } E: \\ldots", "kjør blokka, og håndter feiltype $E$ hvis den oppstår"]],
    legend: [["E", "feiltypen som fanges, f.eks. `ValueError`", ""]],
    ex: "`try:`\n`    x = int(\"abc\")`\n`except ValueError:`\n`    x = 0`\nProgrammet fortsetter med `x = 0` i stedet for å krasje.",
    tip: "Fang den spesifikke feiltypen du forventer — et bredt `except:` skjuler lett andre feil." },
  en: { t: "try / except",
    intro: "`try`/`except` catches and handles errors (exceptions) that occur while the program runs, instead of the whole program crashing. `except ValueError:` catches only that specific error type, so other errors still get through.",
    f: [["\\text{try}: \\ldots \\text{except } E: \\ldots", "run the block, and handle error type $E$ if it occurs"]],
    legend: [["E", "the error type caught, e.g. `ValueError`", ""]],
    ex: "`try:`\n`    x = int(\"abc\")`\n`except ValueError:`\n`    x = 0`\nThe program continues with `x = 0` instead of crashing.",
    tip: "Catch the specific error type you expect — a broad `except:` easily hides other bugs." } }
]);
// ---------------- NUM: Numeriske metoder ----------------
TOPICS("NUM", 0, [
{ id: "halveringsmetoden",
  fig: `<svg viewBox="0 0 240 140"><path d="M20 110H220" class="dim"/><path d="M40 105V115M200 105V115M120 100V120" class="d"/><path d="M30 40C 80 20, 140 120, 210 60" class="d"/><text x="34" y="132">a</text><text x="196" y="132">b</text><text x="114" y="98">m</text></svg>`,
  nb: { t: "Halveringsmetoden",
    intro: "Halveringsmetoden (bisection) finner en rot av $f(x) = 0$ ved å starte med et intervall $[a, b]$ der $f$ skifter fortegn, og gjentatte ganger halvere det. Metoden er robust og garantert å konvergere, men treg: hvert steg halverer bare usikkerheten.",
    f: [["m = \\frac{a+b}{2}", "midtpunktet i intervallet"], ["f(a)\\,f(b) < 0", "kravet for å starte: fortegnsskifte i $[a,b]$"]],
    legend: [["a,\\ b", "intervallets endepunkter", ""], ["m", "midtpunktet, ny endepunkt", ""]],
    ex: "$f(x) = x^2 - 7$ på $[1, 7]$: $m = 4$, $f(4) = 9 > 0$.\nFortegnsskiftet ligger nå i $[1, 4]$, som blir det nye intervallet.",
    tip: "Antall steg for å nå toleranse $\\varepsilon$ er $n \\geq \\log_2\\!\\big((b-a)/\\varepsilon\\big)$." },
  en: { t: "Bisection method",
    intro: "The bisection method finds a root of $f(x) = 0$ by starting with an interval $[a, b]$ where $f$ changes sign, and repeatedly halving it. The method is robust and guaranteed to converge, but slow: each step only halves the uncertainty.",
    f: [["m = \\frac{a+b}{2}", "the midpoint of the interval"], ["f(a)\\,f(b) < 0", "the requirement to start: a sign change in $[a,b]$"]],
    legend: [["a,\\ b", "the endpoints of the interval", ""], ["m", "the midpoint, new endpoint", ""]],
    ex: "$f(x) = x^2 - 7$ on $[1, 7]$: $m = 4$, $f(4) = 9 > 0$.\nThe sign change is now in $[1, 4]$, which becomes the new interval.",
    tip: "The number of steps to reach tolerance $\\varepsilon$ is $n \\geq \\log_2\\!\\big((b-a)/\\varepsilon\\big)$." } },
{ id: "newtons-metode",
  nb: { t: "Newtons metode",
    intro: "Newtons metode finner en rot ved å følge tangenten til $f$ ned til den krysser x-aksen, gjentatte ganger. Nær en enkel rot konvergerer den kvadratisk — antall riktige siffer dobles omtrent for hvert steg — men den trenger den deriverte og kan divergere med dårlig startgjetning.",
    f: [["x_{n+1} = x_n - \\frac{f(x_n)}{f'(x_n)}", "iterasjonsformelen"]],
    legend: [["x_n", "gjeldende tilnærming", ""], ["f'(x_n)", "den deriverte i $x_n$", ""]],
    ex: "$f(x) = x^3 - 5$, $x_0 = 3$:\n$x_1 = 3 - \\frac{27-5}{27} \\approx 2{,}1852$.",
    tip: "Newtons metode kan divergere hvis $f'(x_n)$ er nær null eller startgjetningen er dårlig." },
  en: { t: "Newton's method",
    intro: "Newton's method finds a root by following the tangent of $f$ down to where it crosses the x-axis, repeatedly. Near a simple root it converges quadratically — the number of correct digits roughly doubles each step — but it needs the derivative and can diverge with a poor initial guess.",
    f: [["x_{n+1} = x_n - \\frac{f(x_n)}{f'(x_n)}", "the iteration formula"]],
    legend: [["x_n", "current approximation", ""], ["f'(x_n)", "the derivative at $x_n$", ""]],
    ex: "$f(x) = x^3 - 5$, $x_0 = 3$:\n$x_1 = 3 - \\frac{27-5}{27} \\approx 2.1852$.",
    tip: "Newton's method can diverge if $f'(x_n)$ is near zero or the initial guess is poor." } },
{ id: "sekantmetoden",
  nb: { t: "Sekantmetoden",
    intro: "Sekantmetoden ligner Newtons metode, men bruker en sekantlinje gjennom to punkter i stedet for tangenten, slik at den deriverte ikke trengs. Den konvergerer litt saktere enn Newton (orden $\\approx 1{,}618$), men er nyttig når $f'$ er vanskelig å regne ut.",
    f: [["x_{n+1} = x_n - f(x_n)\\,\\frac{x_n - x_{n-1}}{f(x_n) - f(x_{n-1})}", "iterasjonsformelen, bruker to forrige punkter"]],
    legend: [["x_n,\\ x_{n-1}", "de to siste tilnærmingene", ""]],
    ex: "$f(x) = x^2 - 3$, $x_0 = 1$, $x_1 = 2$:\n$x_2 = 2 - 1\\cdot\\frac{2-1}{1-(-2)} \\approx 1{,}6667$.",
    tip: "Sekantmetoden trenger to startpunkter, ikke bare ett, siden den bruker en linje mellom dem." },
  en: { t: "Secant method",
    intro: "The secant method resembles Newton's method, but uses a secant line through two points instead of the tangent, so the derivative is not needed. It converges a bit slower than Newton (order $\\approx 1.618$), but is useful when $f'$ is hard to compute.",
    f: [["x_{n+1} = x_n - f(x_n)\\,\\frac{x_n - x_{n-1}}{f(x_n) - f(x_{n-1})}", "the iteration formula, uses the two previous points"]],
    legend: [["x_n,\\ x_{n-1}", "the two most recent approximations", ""]],
    ex: "$f(x) = x^2 - 3$, $x_0 = 1$, $x_1 = 2$:\n$x_2 = 2 - 1\\cdot\\frac{2-1}{1-(-2)} \\approx 1.6667$.",
    tip: "The secant method needs two starting points, not just one, since it uses a line between them." } },
{ id: "fikspunktiterasjon",
  nb: { t: "Fikspunktiterasjon",
    intro: "En ligning $f(x) = 0$ kan skrives om til formen $x = g(x)$ og løses ved å iterere $x_{n+1} = g(x_n)$ fra en startverdi. Metoden konvergerer bare hvis $|g'(x)| < 1$ nær roten — ellers vandrer iterasjonene bort fra svaret i stedet for mot det.",
    f: [["x_{n+1} = g(x_n)", "iterasjonen"], ["|g'(x)| < 1", "krav for lokal konvergens nær roten"]],
    legend: [["g", "funksjonen ligningen er omskrevet til", ""]],
    ex: "$x = \\cos x$ kan itereres som $x_{n+1} = \\cos x_n$, som konvergerer siden $|\\!-\\!\\sin x| < 1$ nær roten.",
    tip: "Sjekk alltid $|g'(x)|$ nær forventet rot før du stoler på at iterasjonen konvergerer." },
  en: { t: "Fixed-point iteration",
    intro: "An equation $f(x) = 0$ can be rewritten as $x = g(x)$ and solved by iterating $x_{n+1} = g(x_n)$ from a starting value. The method only converges if $|g'(x)| < 1$ near the root — otherwise the iterations wander away from the answer instead of toward it.",
    f: [["x_{n+1} = g(x_n)", "the iteration"], ["|g'(x)| < 1", "requirement for local convergence near the root"]],
    legend: [["g", "the function the equation is rewritten as", ""]],
    ex: "$x = \\cos x$ can be iterated as $x_{n+1} = \\cos x_n$, which converges since $|\\!-\\!\\sin x| < 1$ near the root.",
    tip: "Always check $|g'(x)|$ near the expected root before trusting that the iteration converges." } }
]);
TOPICS("NUM", 1, [
{ id: "trapesmetoden",
  fig: `<svg viewBox="0 0 240 140"><path d="M30 115H220" class="dim"/><path d="M30 115V25" class="dim"/><path d="M30 100C 90 20, 160 20, 210 60" class="d"/><path d="M30 115V100L 210 60V115Z" class="fill"/><path d="M30 115V100M120 115V80M210 115V60" class="d"/><text x="24" y="130">a</text><text x="204" y="130">b</text></svg>`,
  nb: { t: "Trapesmetoden",
    intro: "Trapesmetoden tilnærmer $\\int_a^b f(x)\\,dx$ ved å erstatte kurven med rette linjestykker mellom punktene, slik at arealet blir en sum av trapeser. Halveres steglengden $h$, blir feilen omtrent en firedel, siden den globale feilen er $O(h^2)$.",
    f: [["\\int_a^b f\\,dx \\approx h\\Big(\\tfrac{f_0}{2} + f_1 + \\cdots + f_{n-1} + \\tfrac{f_n}{2}\\Big)", "trapesregelen med $n$ intervaller"]],
    legend: [["h", "steglengde, $(b-a)/n$", ""], ["f_i", "funksjonsverdi i punkt $i$", ""]],
    ex: "$\\int_0^3 x^2\\,dx$ med 2 intervaller, $h = 1{,}5$:\n$h(f_0/2 + f_1 + f_2/2) = 10{,}125$ (eksakt er 9).",
    tip: "Trapesmetoden overestimerer arealet for en konveks (oppoverbøyd) kurve." },
  en: { t: "Trapezoidal rule",
    intro: "The trapezoidal rule approximates $\\int_a^b f(x)\\,dx$ by replacing the curve with straight segments between the points, so the area becomes a sum of trapezoids. Halving the step size $h$ roughly quarters the error, since the global error is $O(h^2)$.",
    f: [["\\int_a^b f\\,dx \\approx h\\Big(\\tfrac{f_0}{2} + f_1 + \\cdots + f_{n-1} + \\tfrac{f_n}{2}\\Big)", "the trapezoidal rule with $n$ intervals"]],
    legend: [["h", "step size, $(b-a)/n$", ""], ["f_i", "function value at point $i$", ""]],
    ex: "$\\int_0^3 x^2\\,dx$ with 2 intervals, $h = 1.5$:\n$h(f_0/2 + f_1 + f_2/2) = 10.125$ (exact is 9).",
    tip: "The trapezoidal rule overestimates the area for a convex (upward-curving) function." } },
{ id: "simpsons-metode",
  nb: { t: "Simpsons metode",
    intro: "Simpsons metode tilnærmer integralet ved å legge en parabel gjennom hvert par av intervaller, i stedet for en rett linje. Den integrerer polynomer opp til grad 3 eksakt, og feilen er $O(h^4)$ — halveres $h$, blir feilen omtrent en sekstendel.",
    f: [["\\int_{x_0}^{x_2} f\\,dx \\approx \\frac{h}{3}\\big(f_0 + 4f_1 + f_2\\big)", "Simpsons regel over ett dobbeltintervall"]],
    legend: [["h", "steglengde mellom naboverdier", ""], ["f_0, f_1, f_2", "funksjonsverdier i endepunkter og midtpunkt", ""]],
    ex: "$\\int_0^3 x^2\\,dx$ med $h = 1{,}5$:\n$\\frac{h}{3}(f_0 + 4f_1 + f_2) = 9$ — eksakt, siden graden er $2 \\leq 3$.",
    tip: "Simpsons metode trenger et partall antall intervaller (et oddetall punkter)." },
  en: { t: "Simpson's rule",
    intro: "Simpson's rule approximates the integral by fitting a parabola through each pair of intervals, instead of a straight line. It integrates polynomials up to degree 3 exactly, and the error is $O(h^4)$ — halving $h$ roughly cuts the error to a sixteenth.",
    f: [["\\int_{x_0}^{x_2} f\\,dx \\approx \\frac{h}{3}\\big(f_0 + 4f_1 + f_2\\big)", "Simpson's rule over one double interval"]],
    legend: [["h", "step size between neighbouring points", ""], ["f_0, f_1, f_2", "function values at the endpoints and midpoint", ""]],
    ex: "$\\int_0^3 x^2\\,dx$ with $h = 1.5$:\n$\\frac{h}{3}(f_0 + 4f_1 + f_2) = 9$ — exact, since the degree is $2 \\leq 3$.",
    tip: "Simpson's rule needs an even number of intervals (an odd number of points)." } },
{ id: "polynominterpolasjon",
  nb: { t: "Polynominterpolasjon",
    intro: "Interpolasjon finner et polynom som går nøyaktig gjennom et sett med punkter, og brukes til å anslå verdier mellom dem. Et polynom av grad $n$ er entydig bestemt av $n+1$ punkter. Med mange, jevnt fordelte punkter kan høygradige polynomer svinge kraftig nær endene — Runges fenomen.",
    f: [["n+1", "antall punkter som bestemmer et interpolasjonspolynom av grad $n$"]],
    legend: [["n", "polynomets grad", ""]],
    ex: "Lineær interpolasjon mellom $(1, 1)$ og $(5, 1)$ gir $y = 1$ for alle $x$ mellom, siden begge punktene har samme $y$.",
    tip: "Unngå høygradig interpolasjon i jevnt fordelte punkter — bruk Chebyshev-punkter eller splines i stedet." },
  en: { t: "Polynomial interpolation",
    intro: "Interpolation finds a polynomial that passes exactly through a set of points, and is used to estimate values between them. A polynomial of degree $n$ is uniquely determined by $n+1$ points. With many evenly spaced points, high-degree polynomials can oscillate strongly near the ends — Runge's phenomenon.",
    f: [["n+1", "number of points that determine an interpolating polynomial of degree $n$"]],
    legend: [["n", "the degree of the polynomial", ""]],
    ex: "Linear interpolation between $(1, 1)$ and $(5, 1)$ gives $y = 1$ for all $x$ in between, since both points have the same $y$.",
    tip: "Avoid high-degree interpolation at evenly spaced points — use Chebyshev points or splines instead." } },
{ id: "splines-gauss",
  nb: { t: "Splines og Gauss-kvadratur",
    intro: "En spline er et stykkevis polynom som er glatt i skjøtene mellom stykkene; kubiske splines er mest brukt og unngår Runges fenomen. Gauss-kvadratur er en integrasjonsmetode som velger punkter og vekter optimalt, slik at $n$ punkter gir eksakt svar for polynomer opp til grad $2n-1$.",
    f: [["\\int_a^b f\\,dx \\approx \\sum_{i=1}^n w_i f(x_i)", "Gauss-kvadratur med $n$ optimalt valgte punkter og vekter"]],
    legend: [["x_i", "kvadraturpunkter (ikke jevnt fordelt)", ""], ["w_i", "vektene til hvert punkt", ""]],
    ex: "Med $n = 2$ punkter gir Gauss-kvadratur eksakt svar for alle polynomer opp til grad $2\\cdot 2 - 1 = 3$.",
    tip: "Gauss-kvadratur trenger langt færre punkter enn trapes/Simpson for samme nøyaktighet, men punktene er ikke jevnt fordelt." },
  en: { t: "Splines and Gaussian quadrature",
    intro: "A spline is a piecewise polynomial that is smooth across the joints between pieces; cubic splines are most common and avoid Runge's phenomenon. Gaussian quadrature is an integration method that chooses points and weights optimally, so that $n$ points give an exact answer for polynomials up to degree $2n-1$.",
    f: [["\\int_a^b f\\,dx \\approx \\sum_{i=1}^n w_i f(x_i)", "Gaussian quadrature with $n$ optimally chosen points and weights"]],
    legend: [["x_i", "quadrature points (not evenly spaced)", ""], ["w_i", "the weight of each point", ""]],
    ex: "With $n = 2$ points, Gaussian quadrature gives an exact answer for all polynomials up to degree $2\\cdot 2 - 1 = 3$.",
    tip: "Gaussian quadrature needs far fewer points than trapezoid/Simpson for the same accuracy, but the points are not evenly spaced." } }
]);
TOPICS("NUM", 2, [
{ id: "eulers-metode",
  fig: `<svg viewBox="0 0 240 140"><path d="M25 110H225" class="dim"/><path d="M25 110V20" class="dim"/><path d="M35 95C 90 30, 150 25, 210 45" class="dash"/><path d="M35 95L80 78L125 68L170 60L210 55" class="d"/><circle cx="35" cy="95" r="3" class="af"/><circle cx="80" cy="78" r="3" class="af"/><circle cx="125" cy="68" r="3" class="af"/><circle cx="170" cy="60" r="3" class="af"/><text x="20" y="105">y₀</text></svg>`,
  nb: { t: "Eulers metode",
    intro: "Eulers eksplisitte metode løser en ODE $y' = f(t, y)$ numerisk ved å følge stigningstallet fra hvert punkt et lite steg $h$ fremover. Den er enkel, men har lav orden: den globale feilen er $O(h)$, så det trengs korte steg for god nøyaktighet.",
    f: [["y_{n+1} = y_n + h\\,f(t_n, y_n)", "ett Euler-steg"]],
    legend: [["h", "steglengde", ""], ["f(t_n, y_n)", "stigningstallet (helningen) ved $(t_n, y_n)$", ""]],
    ex: "$y' = y$, $y_0 = 2$, $h = 0{,}1$: hvert steg ganges med $1{,}1$.\n$y_2 = 2\\cdot 1{,}1^2 = 2{,}42$.",
    tip: "Halverer du $h$, halveres omtrent den globale feilen — Euler har bare første ordens nøyaktighet." },
  en: { t: "Euler's method",
    intro: "Euler's explicit method solves an ODE $y' = f(t, y)$ numerically by following the slope from each point a small step $h$ forward. It is simple but low order: the global error is $O(h)$, so short steps are needed for good accuracy.",
    f: [["y_{n+1} = y_n + h\\,f(t_n, y_n)", "one Euler step"]],
    legend: [["h", "step size", ""], ["f(t_n, y_n)", "the slope at $(t_n, y_n)$", ""]],
    ex: "$y' = y$, $y_0 = 2$, $h = 0.1$: each step is multiplied by $1.1$.\n$y_2 = 2\\cdot 1.1^2 = 2.42$.",
    tip: "Halving $h$ roughly halves the global error — Euler only has first-order accuracy." } },
{ id: "runge-kutta",
  nb: { t: "Runge–Kutta (RK4)",
    intro: "Den klassiske Runge–Kutta-metoden (RK4) er en fjerde ordens metode som bruker fire funksjonsevalueringer per steg for å anslå stigningstallet mer nøyaktig enn Euler. Global feil er $O(h^4)$, så en liten reduksjon i $h$ gir stor gevinst i nøyaktighet.",
    f: [["y_{n+1} = y_n + \\tfrac{h}{6}(k_1 + 2k_2 + 2k_3 + k_4)", "RK4-oppdateringen"]],
    legend: [["k_1,\\ldots,k_4", "fire stigningstall evaluert på ulike steder i steget", ""]],
    ex: "Deles steglengden med 10 i en metode av orden 2 (Heun), blir feilen omtrent $10^2 = 100$ ganger mindre; for RK4 blir den $10^4$ ganger mindre.",
    tip: "RK4 er dyrere per steg enn Euler (fire evalueringer mot én), men lønner seg nesten alltid på nøyaktighet." },
  en: { t: "Runge–Kutta (RK4)",
    intro: "The classic Runge–Kutta method (RK4) is a fourth-order method that uses four function evaluations per step to estimate the slope more accurately than Euler. Global error is $O(h^4)$, so a small reduction in $h$ gives a large gain in accuracy.",
    f: [["y_{n+1} = y_n + \\tfrac{h}{6}(k_1 + 2k_2 + 2k_3 + k_4)", "the RK4 update"]],
    legend: [["k_1,\\ldots,k_4", "four slopes evaluated at different points within the step", ""]],
    ex: "Dividing the step size by 10 in an order-2 method (Heun) makes the error roughly $10^2 = 100$ times smaller; for RK4 it becomes $10^4$ times smaller.",
    tip: "RK4 is more expensive per step than Euler (four evaluations versus one), but it almost always pays off in accuracy." } },
{ id: "stivhet-stabilitet",
  nb: { t: "Stivhet og stabilitet",
    intro: "Et stivt (stiff) problem har svært ulike tidsskalaer, slik at en eksplisitt metode som Euler trenger bittesmå steg for å holde seg stabil, selv om løsningen ellers endrer seg sakte. Stabilitetsgrensen for eksplisitt Euler på $y' = \\lambda y$ er $h \\leq 2/|\\lambda|$.",
    f: [["|1 + h\\lambda| \\leq 1", "stabilitetskrav for eksplisitt Euler på $y' = \\lambda y$"]],
    legend: [["\\lambda", "vekstraten i ligningen (negativ for avtagende løsning)", ""], ["h", "steglengde", ""]],
    ex: "$y' = -50y$: stabilitet krever $h \\leq 2/50 = 0{,}04$.\nStørre steg gir en løsning som svinger og vokser urealistisk.",
    tip: "For stive problemer, bytt til en implisitt metode (f.eks. bakover-Euler) i stedet for å bare korte ned $h$." },
  en: { t: "Stiffness and stability",
    intro: "A stiff problem has widely different time scales, so an explicit method like Euler needs tiny steps to stay stable, even though the solution otherwise changes slowly. The stability limit for explicit Euler on $y' = \\lambda y$ is $h \\leq 2/|\\lambda|$.",
    f: [["|1 + h\\lambda| \\leq 1", "stability requirement for explicit Euler on $y' = \\lambda y$"]],
    legend: [["\\lambda", "the growth rate in the equation (negative for a decaying solution)", ""], ["h", "step size", ""]],
    ex: "$y' = -50y$: stability requires $h \\leq 2/50 = 0.04$.\nA larger step gives a solution that oscillates and grows unrealistically.",
    tip: "For stiff problems, switch to an implicit method (e.g. backward Euler) instead of just shortening $h$." } },
{ id: "system-av-forste-orden",
  nb: { t: "System av første ordens ligninger",
    intro: "De fleste numeriske løsere er laget for systemer av første ordens ligninger, så en høyere ordens ODE skrives om ved å innføre nye variabler for de deriverte. En andreordens ligning $y'' = f(t, y, y')$ blir da to koblede førsteordens ligninger.",
    f: [["y_1 = y,\\ y_2 = y'", "nye variabler"], ["y_1' = y_2,\\quad y_2' = f(t, y_1, y_2)", "systemet av første orden"]],
    legend: [["y_1, y_2", "posisjon og hastighet som separate ukjente", ""]],
    ex: "$y'' + 3y' + 2y = 0$ blir $y_1' = y_2$ og $y_2' = -3y_2 - 2y_1$, løst med f.eks. RK4 på vektoren $(y_1, y_2)$.",
    tip: "Denne omskrivingen er nøkkelen til å bruke Euler eller Runge–Kutta på ligninger av høyere orden." },
  en: { t: "System of first-order equations",
    intro: "Most numerical solvers are built for systems of first-order equations, so a higher-order ODE is rewritten by introducing new variables for the derivatives. A second-order equation $y'' = f(t, y, y')$ then becomes two coupled first-order equations.",
    f: [["y_1 = y,\\ y_2 = y'", "new variables"], ["y_1' = y_2,\\quad y_2' = f(t, y_1, y_2)", "the first-order system"]],
    legend: [["y_1, y_2", "position and velocity as separate unknowns", ""]],
    ex: "$y'' + 3y' + 2y = 0$ becomes $y_1' = y_2$ and $y_2' = -3y_2 - 2y_1$, solved with e.g. RK4 on the vector $(y_1, y_2)$.",
    tip: "This rewriting is the key to applying Euler or Runge–Kutta to higher-order equations." } }
]);
// ---------------- MEK2200: Statistikk og risikoanalyse ----------------
TOPICS("MEK2200", 0, [
{ id: "union-og-komplement",
  nb: { t: "Union, snitt og komplement",
    intro: "For to hendelser $A$ og $B$ gir unionsregelen sannsynligheten for at minst én av dem skjer; snittet $A\\cap B$ må trekkes fra så det ikke telles to ganger. Komplementet $A^c$ er nyttig for «minst én»-spørsmål, siden det ofte er lettere å regne ut motsatt hendelse.",
    f: [["P(A\\cup B) = P(A) + P(B) - P(A\\cap B)", "sannsynlighet for $A$ eller $B$"], ["P(A^c) = 1 - P(A)", "komplementregelen"]],
    legend: [["A\\cup B", "$A$ eller $B$ (eller begge)", ""], ["A\\cap B", "$A$ og $B$ samtidig", ""], ["A^c", "komplementet til $A$ (ikke $A$)", ""]],
    ex: "$P(A) = 0{,}45$, $P(B) = 0{,}65$, $P(A\\cap B) = 0{,}15$:\n$P(A\\cup B) = 0{,}45 + 0{,}65 - 0{,}15 = 0{,}95$.",
    tip: "«Minst én av $n$» er ofte enklest å finne som $1 -$ sannsynligheten for at ingen skjer." },
  en: { t: "Union, intersection and complement",
    intro: "For two events $A$ and $B$, the union rule gives the probability that at least one of them occurs; the intersection $A\\cap B$ must be subtracted so it is not counted twice. The complement $A^c$ is useful for \"at least one\" questions, since it is often easier to compute the opposite event.",
    f: [["P(A\\cup B) = P(A) + P(B) - P(A\\cap B)", "probability of $A$ or $B$"], ["P(A^c) = 1 - P(A)", "the complement rule"]],
    legend: [["A\\cup B", "$A$ or $B$ (or both)", ""], ["A\\cap B", "$A$ and $B$ together", ""], ["A^c", "the complement of $A$ (not $A$)", ""]],
    ex: "$P(A) = 0.45$, $P(B) = 0.65$, $P(A\\cap B) = 0.15$:\n$P(A\\cup B) = 0.45 + 0.65 - 0.15 = 0.95$.",
    tip: "\"At least one of $n$\" is often easiest to find as $1 -$ the probability that none occur." } },
{ id: "serie-parallell-palitelighet",
  fig: `<svg viewBox="0 0 240 140"><path d="M20 70H60M100 70H140M180 70H220" class="dim"/><rect x="60" y="55" width="40" height="30" class="fill"/><rect x="140" y="55" width="40" height="30" class="fill"/><text x="72" y="75">A</text><text x="152" y="75">B</text></svg>`,
  nb: { t: "Serie- og parallellsystemer",
    intro: "I et seriesystem må alle komponenter virke for at systemet skal virke, så påliteligheten er produktet av hver komponents pålitelighet. I et parallellsystem holder det at minst én virker, så systemet svikter bare hvis alle svikter samtidig.",
    f: [["R_{\\text{serie}} = \\prod_i R_i", "alle komponenter må virke"], ["R_{\\text{parallell}} = 1 - \\prod_i (1 - R_i)", "minst én komponent må virke"]],
    legend: [["R_i", "pålitelighet (sannsynlighet for at komponent $i$ virker)", ""]],
    ex: "To komponenter med $R = 0{,}9$ hver:\nI serie: $0{,}9^2 = 0{,}81$. I parallell: $1 - 0{,}1^2 = 0{,}99$.",
    tip: "Parallellkobling øker alltid påliteligheten sammenlignet med én komponent — serie senker den alltid." },
  en: { t: "Series and parallel systems",
    intro: "In a series system all components must work for the system to work, so the reliability is the product of each component's reliability. In a parallel system it is enough that at least one works, so the system only fails if all fail together.",
    f: [["R_{\\text{series}} = \\prod_i R_i", "all components must work"], ["R_{\\text{parallel}} = 1 - \\prod_i (1 - R_i)", "at least one component must work"]],
    legend: [["R_i", "reliability (probability that component $i$ works)", ""]],
    ex: "Two components with $R = 0.9$ each:\nIn series: $0.9^2 = 0.81$. In parallel: $1 - 0.1^2 = 0.99$.",
    tip: "A parallel connection always increases reliability compared to one component — series always lowers it." } },
{ id: "bayes-setning",
  nb: { t: "Bayes' setning",
    intro: "Bayes' setning snur en betinget sannsynlighet: fra $P(B|A)$ finner du $P(A|B)$. Den brukes mye i testing, der man kjenner sannsynligheten for et positivt testresultat gitt sykdom, men ønsker sannsynligheten for sykdom gitt et positivt resultat.",
    f: [["P(A|B) = \\frac{P(B|A)\\,P(A)}{P(B)}", "Bayes' setning"]],
    legend: [["P(A)", "sannsynlighet for $A$ før man vet om $B$", ""], ["P(A|B)", "sannsynlighet for $A$ gitt at $B$ har skjedd", ""]],
    ex: "6 % feilrate, testen finner feilen 99 % av gangene og slår falskt ut på 10 % av de feilfrie.\n$P(\\text{feil}|\\text{utslag}) = \\dfrac{0{,}99\\cdot 0{,}06}{0{,}99\\cdot 0{,}06 + 0{,}1\\cdot 0{,}94} \\approx 0{,}387$.",
    tip: "Regn alltid ut nevneren $P(B)$ ved å summere over alle måter $B$ kan skje på (positiv test, syk eller frisk)." },
  en: { t: "Bayes' theorem",
    intro: "Bayes' theorem flips a conditional probability: from $P(B|A)$ you find $P(A|B)$. It is widely used in testing, where you know the probability of a positive result given disease, but want the probability of disease given a positive result.",
    f: [["P(A|B) = \\frac{P(B|A)\\,P(A)}{P(B)}", "Bayes' theorem"]],
    legend: [["P(A)", "probability of $A$ before knowing about $B$", ""], ["P(A|B)", "probability of $A$ given that $B$ has occurred", ""]],
    ex: "6% defect rate, the test finds the defect 99% of the time and false-positives 10% of the time on good units.\n$P(\\text{defect}|\\text{positive}) = \\dfrac{0.99\\cdot 0.06}{0.99\\cdot 0.06 + 0.1\\cdot 0.94} \\approx 0.387$.",
    tip: "Always compute the denominator $P(B)$ by summing over all the ways $B$ can happen (positive test, sick or healthy)." } },
{ id: "uavhengighet-kombinatorikk",
  nb: { t: "Uavhengighet og kombinatorikk",
    intro: "To hendelser er uavhengige når $P(A\\cap B) = P(A)P(B)$ — at den ene skjer, endrer ikke sannsynligheten for den andre. Fakultet $n!$ teller antall rekkefølger av $n$ ulike ting, mens binomialkoeffisienten $\\binom{n}{k}$ teller antall måter å velge $k$ av $n$ når rekkefølgen ikke betyr noe.",
    f: [["P(A\\cap B) = P(A)P(B)", "krav for uavhengighet"], ["\\binom{n}{k} = \\frac{n!}{k!(n-k)!}", "antall måter å velge $k$ av $n$"]],
    legend: [["n", "totalt antall elementer", ""], ["k", "antall som velges", ""]],
    ex: "Å velge 3 av 4 komponenter: $\\binom{4}{3} = 4$ måter.\nÅ ordne 6 ulike deler: $6! = 720$ rekkefølger.",
    tip: "Disjunkte hendelser (kan ikke skje samtidig) er nesten aldri uavhengige — de er tvert imot sterkt avhengige." },
  en: { t: "Independence and combinatorics",
    intro: "Two events are independent when $P(A\\cap B) = P(A)P(B)$ — one happening does not change the probability of the other. Factorial $n!$ counts the number of orderings of $n$ distinct things, while the binomial coefficient $\\binom{n}{k}$ counts the number of ways to choose $k$ of $n$ when order does not matter.",
    f: [["P(A\\cap B) = P(A)P(B)", "requirement for independence"], ["\\binom{n}{k} = \\frac{n!}{k!(n-k)!}", "number of ways to choose $k$ of $n$"]],
    legend: [["n", "total number of items", ""], ["k", "number chosen", ""]],
    ex: "Choosing 3 of 4 components: $\\binom{4}{3} = 4$ ways.\nOrdering 6 distinct parts: $6! = 720$ orderings.",
    tip: "Disjoint events (cannot happen together) are almost never independent — they are in fact strongly dependent." } }
]);
TOPICS("MEK2200", 1, [
{ id: "normalfordeling",
  fig: `<svg viewBox="0 0 240 140"><path d="M20 115H220" class="dim"/><path d="M120 115V30" class="dim"/><path d="M30 112C 70 112, 90 20, 120 20 S 170 112, 210 112" class="d"/><path d="M76 112V60M164 112V60" class="dash"/><text x="112" y="130">μ</text><text x="70" y="128">μ-2σ</text><text x="150" y="128">μ+2σ</text></svg>`,
  nb: { t: "Normalfordeling og z-verdi",
    intro: "Normalfordelingen er klokkeformet og symmetrisk om forventningen $\\mu$, med spredning gitt av $\\sigma$. 68–95–99,7-regelen sier hvor mye sannsynlighet som ligger innenfor 1, 2 og 3 standardavvik. z-verdien standardiserer en måling til antall standardavvik fra $\\mu$.",
    f: [["z = \\frac{x - \\mu}{\\sigma}", "z-verdi (standardisert avvik)"], ["\\mu \\pm 2\\sigma \\approx 95\\%", "68–95–99,7-regelen for $\\pm1, \\pm2, \\pm3\\sigma$"]],
    legend: [["\\mu", "forventningsverdi", ""], ["\\sigma", "standardavvik", ""], ["z", "antall standardavvik fra $\\mu$", ""]],
    ex: "$\\mu = 76$, $\\sigma = 4$, $x = 72$:\n$z = (72-76)/4 = -1$.",
    tip: "En negativ z-verdi betyr at målingen ligger under gjennomsnittet, ikke at noe er feil." },
  en: { t: "Normal distribution and z-score",
    intro: "The normal distribution is bell-shaped and symmetric about the mean $\\mu$, with spread given by $\\sigma$. The 68–95–99.7 rule states how much probability lies within 1, 2 and 3 standard deviations. The z-score standardizes a measurement to the number of standard deviations from $\\mu$.",
    f: [["z = \\frac{x - \\mu}{\\sigma}", "z-score (standardized deviation)"], ["\\mu \\pm 2\\sigma \\approx 95\\%", "the 68–95–99.7 rule for $\\pm1, \\pm2, \\pm3\\sigma$"]],
    legend: [["\\mu", "expected value", ""], ["\\sigma", "standard deviation", ""], ["z", "number of standard deviations from $\\mu$", ""]],
    ex: "$\\mu = 76$, $\\sigma = 4$, $x = 72$:\n$z = (72-76)/4 = -1$.",
    tip: "A negative z-score means the measurement is below average, not that something is wrong." } },
{ id: "binomisk-fordeling",
  nb: { t: "Binomisk fordeling",
    intro: "Binomisk fordeling $\\text{Bin}(n, p)$ beskriver antall suksesser i $n$ uavhengige forsøk der hvert forsøk har suksesssannsynlighet $p$, som ved antall defekte i et utvalg med tilbakelegging. Forventningsverdien er enkel å regne ut direkte fra $n$ og $p$.",
    f: [["E[X] = np", "forventet antall suksesser"], ["X \\sim \\text{Bin}(n, p)", "$n$ uavhengige forsøk, suksesssannsynlighet $p$"]],
    legend: [["n", "antall forsøk", ""], ["p", "suksesssannsynlighet per forsøk", ""], ["X", "antall suksesser", ""]],
    ex: "$X \\sim \\text{Bin}(10,\\ 0{,}5)$:\n$E[X] = 10\\cdot 0{,}5 = 5$.",
    tip: "Bruk binomisk fordeling når hvert forsøk er uavhengig og har samme suksesssannsynlighet." },
  en: { t: "Binomial distribution",
    intro: "The binomial distribution $\\text{Bin}(n, p)$ describes the number of successes in $n$ independent trials where each trial has success probability $p$, such as the number of defects in a sample with replacement. The expected value is simple to compute directly from $n$ and $p$.",
    f: [["E[X] = np", "expected number of successes"], ["X \\sim \\text{Bin}(n, p)", "$n$ independent trials, success probability $p$"]],
    legend: [["n", "number of trials", ""], ["p", "success probability per trial", ""], ["X", "number of successes", ""]],
    ex: "$X \\sim \\text{Bin}(10,\\ 0.5)$:\n$E[X] = 10\\cdot 0.5 = 5$.",
    tip: "Use the binomial distribution when each trial is independent with the same success probability." } },
{ id: "poisson-eksponential",
  nb: { t: "Poisson- og eksponentialfordeling",
    intro: "Poissonfordelingen modellerer antall hendelser i et fast tidsintervall, som antall feil per time. Eksponentialfordelingen modellerer tiden mellom slike hendelser, og brukes ofte for levetid ved konstant feilrate. De to henger sammen: hvis hendelser er Poisson-fordelt, er tiden mellom dem eksponentialfordelt.",
    f: [["P(X = k) = \\frac{\\lambda^k e^{-\\lambda}}{k!}", "Poisson: sannsynlighet for $k$ hendelser"], ["P(T > t) = e^{-t/\\theta}", "eksponential: sannsynlighet for levetid over $t$"]],
    legend: [["\\lambda", "gjennomsnittlig antall hendelser per intervall", ""], ["\\theta", "forventet levetid", ""]],
    ex: "$\\lambda = 4$ feil per time: $P(X=2) = \\dfrac{4^2 e^{-4}}{2!} \\approx 0{,}1465$.\nForventet levetid 1000 t: $P(T > 500) = e^{-0{,}5} \\approx 0{,}6065$.",
    tip: "Poisson teller hendelser, eksponential måler tiden mellom dem — begge styres av samme rate." },
  en: { t: "Poisson and exponential distribution",
    intro: "The Poisson distribution models the number of events in a fixed time interval, such as the number of failures per hour. The exponential distribution models the time between such events, and is often used for lifetime with a constant failure rate. The two are linked: if events are Poisson distributed, the time between them is exponentially distributed.",
    f: [["P(X = k) = \\frac{\\lambda^k e^{-\\lambda}}{k!}", "Poisson: probability of $k$ events"], ["P(T > t) = e^{-t/\\theta}", "exponential: probability of lifetime beyond $t$"]],
    legend: [["\\lambda", "average number of events per interval", ""], ["\\theta", "expected lifetime", ""]],
    ex: "$\\lambda = 4$ failures per hour: $P(X=2) = \\dfrac{4^2 e^{-4}}{2!} \\approx 0.1465$.\nExpected lifetime 1000 h: $P(T > 500) = e^{-0.5} \\approx 0.6065$.",
    tip: "Poisson counts events, exponential measures the time between them — both are governed by the same rate." } },
{ id: "sentraltendens-spredning",
  nb: { t: "Gjennomsnitt, median og standardavvik",
    intro: "Gjennomsnittet er summen delt på antallet, mens medianen er den midterste verdien i sortert rekkefølge, og er mindre følsom for ekstremverdier. Utvalgsvariansen $s^2$ bruker $n-1$ i nevneren, og standardavviket $s$ er kvadratroten av variansen — det har samme enhet som dataene.",
    f: [["\\bar x = \\frac{1}{n}\\sum_i x_i", "gjennomsnitt"], ["s^2 = \\frac{1}{n-1}\\sum_i (x_i - \\bar x)^2", "utvalgsvarians"], ["s = \\sqrt{s^2}", "utvalgets standardavvik"]],
    legend: [["\\bar x", "gjennomsnitt av utvalget", ""], ["n", "antall observasjoner", ""], ["s", "utvalgets standardavvik", ""]],
    ex: "Data: 2, 4, 4, 4, 5, 5, 7, 9. Sum $= 40$, $\\bar x = 40/8 = 5$.\nMedianen av samme data (sortert, 8 verdier) er snittet av de to midterste: $4{,}5$.",
    tip: "Bruk $n-1$ (ikke $n$) i utvalgsvariansen — det gir et forventningsrett anslag på populasjonsvariansen." },
  en: { t: "Mean, median and standard deviation",
    intro: "The mean is the sum divided by the count, while the median is the middle value in sorted order, and is less sensitive to extreme values. The sample variance $s^2$ uses $n-1$ in the denominator, and the standard deviation $s$ is the square root of the variance — it has the same unit as the data.",
    f: [["\\bar x = \\frac{1}{n}\\sum_i x_i", "mean"], ["s^2 = \\frac{1}{n-1}\\sum_i (x_i - \\bar x)^2", "sample variance"], ["s = \\sqrt{s^2}", "sample standard deviation"]],
    legend: [["\\bar x", "mean of the sample", ""], ["n", "number of observations", ""], ["s", "sample standard deviation", ""]],
    ex: "Data: 2, 4, 4, 4, 5, 5, 7, 9. Sum $= 40$, $\\bar x = 40/8 = 5$.\nThe median of the same data (sorted, 8 values) is the average of the two middle values: $4.5$.",
    tip: "Use $n-1$ (not $n$) in the sample variance — it gives an unbiased estimate of the population variance." } }
]);
TOPICS("MEK2200", 2, [
{ id: "hypotesetesting",
  nb: { t: "Hypotesetesting og p-verdi",
    intro: "En hypotesetest sjekker om data er forenlig med en nullhypotese $H_0$. p-verdien er sannsynligheten for et minst like ekstremt resultat som det observerte, gitt at $H_0$ er sann. Er p-verdien lavere enn signifikansnivået $\\alpha$, forkastes $H_0$.",
    f: [["p < \\alpha \\Rightarrow \\text{forkast } H_0", "beslutningsregel"]],
    legend: [["\\alpha", "signifikansnivå, ofte 0,05", ""], ["p", "p-verdi fra testen", ""]],
    ex: "Med $\\alpha = 0{,}05$ og $p = 0{,}02$ forkastes $H_0$: dataene passer dårlig med den.",
    tip: "En lav p-verdi betyr at dataene er usannsynlige under $H_0$ — den sier ikke at $H_0$ er falsk med sikkerhet." },
  en: { t: "Hypothesis testing and p-value",
    intro: "A hypothesis test checks whether data is consistent with a null hypothesis $H_0$. The p-value is the probability of a result at least as extreme as the one observed, given that $H_0$ is true. If the p-value is below the significance level $\\alpha$, $H_0$ is rejected.",
    f: [["p < \\alpha \\Rightarrow \\text{reject } H_0", "decision rule"]],
    legend: [["\\alpha", "significance level, often 0.05", ""], ["p", "p-value from the test", ""]],
    ex: "With $\\alpha = 0.05$ and $p = 0.02$, $H_0$ is rejected: the data fits it poorly.",
    tip: "A low p-value means the data is unlikely under $H_0$ — it does not mean $H_0$ is certainly false." } },
{ id: "konfidensintervall",
  nb: { t: "Konfidensintervall",
    intro: "Et konfidensintervall gir et intervall av sannsynlige verdier for en ukjent størrelse, som forventningen $\\mu$, basert på et utvalg. Standardfeilen til gjennomsnittet avtar med $\\sqrt n$, så et større utvalg gir et smalere intervall. Et høyere konfidensnivå gir et bredere intervall.",
    f: [["\\bar x \\pm z_{\\alpha/2}\\,\\frac{\\sigma}{\\sqrt n}", "konfidensintervall for $\\mu$ ved kjent $\\sigma$"], ["SE = \\frac{\\sigma}{\\sqrt n}", "standardfeilen til gjennomsnittet"]],
    legend: [["\\bar x", "gjennomsnitt i utvalget", ""], ["z_{\\alpha/2}", "kritisk z-verdi, 1,96 for 95 %", ""], ["n", "utvalgsstørrelse", ""]],
    ex: "$\\bar x = 35$, $\\sigma = 18$, $n = 36$: $SE = 18/6 = 3$.\nØvre grense i 95 %-intervall: $35 + 1{,}96\\cdot 3 \\approx 40{,}88$.",
    tip: "Et bredere intervall betyr høyere sikkerhet, ikke dårligere data — konfidensnivå og presisjon veies mot hverandre." },
  en: { t: "Confidence interval",
    intro: "A confidence interval gives a range of plausible values for an unknown quantity, such as the mean $\\mu$, based on a sample. The standard error of the mean shrinks with $\\sqrt n$, so a larger sample gives a narrower interval. A higher confidence level gives a wider interval.",
    f: [["\\bar x \\pm z_{\\alpha/2}\\,\\frac{\\sigma}{\\sqrt n}", "confidence interval for $\\mu$ with known $\\sigma$"], ["SE = \\frac{\\sigma}{\\sqrt n}", "standard error of the mean"]],
    legend: [["\\bar x", "sample mean", ""], ["z_{\\alpha/2}", "critical z-value, 1.96 for 95%", ""], ["n", "sample size", ""]],
    ex: "$\\bar x = 35$, $\\sigma = 18$, $n = 36$: $SE = 18/6 = 3$.\nUpper bound of 95% interval: $35 + 1.96\\cdot 3 \\approx 40.88$.",
    tip: "A wider interval means higher confidence, not worse data — confidence level and precision are traded off." } },
{ id: "type-i-ii-feil",
  nb: { t: "Type I- og type II-feil",
    intro: "En type I-feil er å forkaste en sann $H_0$; sannsynligheten for dette er signifikansnivået $\\alpha$. En type II-feil er å beholde en usann $H_0$, med sannsynlighet $\\beta$. Testens styrke, $1-\\beta$, er sannsynligheten for å oppdage en reell effekt når den finnes.",
    f: [["\\alpha = P(\\text{forkaste } H_0 \\mid H_0 \\text{ sann})", "type I-feil"], ["\\beta = P(\\text{beholde } H_0 \\mid H_0 \\text{ usann})", "type II-feil"]],
    legend: [["\\alpha", "signifikansnivå", ""], ["\\beta", "sannsynlighet for type II-feil", ""], ["1-\\beta", "testens styrke", ""]],
    ex: "Senkes $\\alpha$ (strengere krav for å forkaste $H_0$), øker vanligvis $\\beta$ for samme utvalgsstørrelse.",
    tip: "Type I og type II er motsatte feil — å redusere den ene øker som regel den andre, med mindre $n$ økes." },
  en: { t: "Type I and type II errors",
    intro: "A type I error is rejecting a true $H_0$; its probability is the significance level $\\alpha$. A type II error is retaining a false $H_0$, with probability $\\beta$. The test's power, $1-\\beta$, is the probability of detecting a real effect when one exists.",
    f: [["\\alpha = P(\\text{reject } H_0 \\mid H_0 \\text{ true})", "type I error"], ["\\beta = P(\\text{retain } H_0 \\mid H_0 \\text{ false})", "type II error"]],
    legend: [["\\alpha", "significance level", ""], ["\\beta", "probability of a type II error", ""], ["1-\\beta", "the test's power", ""]],
    ex: "Lowering $\\alpha$ (a stricter requirement to reject $H_0$) usually increases $\\beta$ for the same sample size.",
    tip: "Type I and type II are opposite errors — reducing one usually increases the other, unless $n$ is increased." } },
{ id: "risiko-og-alarp",
  nb: { t: "Risiko, risikomatrise og ALARP",
    intro: "Risiko defineres ofte som sannsynlighet ganger konsekvens, slik at man kan prioritere tiltak mot det som både er sannsynlig og alvorlig. En risikomatrise visualiserer dette i to akser. ALARP («As Low As Reasonably Practicable») betyr at risiko skal reduseres så langt som praktisk mulig, ikke nødvendigvis til null.",
    f: [["\\text{Risiko} = \\text{sannsynlighet} \\times \\text{konsekvens}", "grunnleggende risikoformel"]],
    legend: [],
    ex: "Sannsynlighet $0{,}001$ per år, konsekvens 50 000 kr:\nForventet årlig tap $= 0{,}001\\cdot 50\\,000 = 50$ kr.",
    tip: "Høy sannsynlighet med lav konsekvens kan gi samme risiko som lav sannsynlighet med høy konsekvens — begge må vurderes." },
  en: { t: "Risk, risk matrix and ALARP",
    intro: "Risk is often defined as probability times consequence, so that measures can be prioritized against what is both likely and severe. A risk matrix visualizes this on two axes. ALARP (\"As Low As Reasonably Practicable\") means risk should be reduced as far as is practically possible, not necessarily to zero.",
    f: [["\\text{Risk} = \\text{probability} \\times \\text{consequence}", "basic risk formula"]],
    legend: [],
    ex: "Probability $0.001$ per year, consequence 50,000 kr:\nExpected annual loss $= 0.001\\cdot 50{,}000 = 50$ kr.",
    tip: "High probability with low consequence can give the same risk as low probability with high consequence — both must be assessed." } },
{ id: "mtbf-mttr",
  nb: { t: "MTBF, MTTR og tilgjengelighet",
    intro: "MTBF (Mean Time Between Failures) er gjennomsnittlig tid mellom feil, mens MTTR (Mean Time To Repair) er gjennomsnittlig reparasjonstid. Tilgjengeligheten er andelen tid systemet faktisk virker, og øker med høyere MTBF og lavere MTTR. For konstant feilrate er feilraten $\\lambda$ den inverse av MTBF.",
    f: [["A = \\frac{MTBF}{MTBF + MTTR}", "tilgjengelighet"], ["\\lambda = \\frac{1}{MTBF}", "feilrate ved konstant feilrate"]],
    legend: [["MTBF", "gjennomsnittlig tid mellom feil", "h"], ["MTTR", "gjennomsnittlig reparasjonstid", "h"], ["A", "tilgjengelighet, andel av tiden", ""]],
    ex: "MTBF $= 5000$ h, MTTR $= 2$ h:\n$A = 5000/5002 \\approx 0{,}9996$, altså 99,96 % oppetid.",
    tip: "Tilgjengelighet nær 1 krever enten svært høy MTBF eller svært lav MTTR — helst begge deler." },
  en: { t: "MTBF, MTTR and availability",
    intro: "MTBF (Mean Time Between Failures) is the average time between failures, while MTTR (Mean Time To Repair) is the average repair time. Availability is the fraction of time the system actually works, and increases with higher MTBF and lower MTTR. For a constant failure rate, the failure rate $\\lambda$ is the inverse of MTBF.",
    f: [["A = \\frac{MTBF}{MTBF + MTTR}", "availability"], ["\\lambda = \\frac{1}{MTBF}", "failure rate with constant failure rate"]],
    legend: [["MTBF", "average time between failures", "h"], ["MTTR", "average repair time", "h"], ["A", "availability, fraction of time", ""]],
    ex: "MTBF $= 5000$ h, MTTR $= 2$ h:\n$A = 5000/5002 \\approx 0.9996$, i.e. 99.96% uptime.",
    tip: "Availability near 1 requires either very high MTBF or very low MTTR — ideally both." } }
]);
// ---------------- OKON: Ingeniørøkonomi ----------------
TOPICS("OKON", 0, [
{ id: "naverdi-diskontering",
  nb: { t: "Nåverdi og diskontering",
    intro: "Penger i dag er verdt mer enn samme beløp i fremtiden, fordi de kan forrentes i mellomtiden. Nåverdien av et fremtidig beløp finnes ved å diskontere det med en kalkulasjonsrente. Motsatt gir sluttverdien hva et beløp i dag vokser til etter $n$ år med rentes rente.",
    f: [["P = \\frac{F}{(1+r)^n}", "nåverdi av beløpet $F$ om $n$ år"], ["F = P(1+r)^n", "sluttverdi av beløpet $P$ i dag"]],
    legend: [["P", "nåverdi (i dag)", "kr"], ["F", "fremtidig verdi", "kr"], ["r", "kalkulasjonsrente per år", ""], ["n", "antall år", ""]],
    ex: "10 000 kr om 14 år, kalkulasjonsrente 8 %:\n$P = 10000/1{,}08^{14} \\approx 3405$ kr.",
    tip: "Jo lenger frem i tid og jo høyere rente, desto mindre er nåverdien av et fremtidig beløp." },
  en: { t: "Present value and discounting",
    intro: "Money today is worth more than the same amount in the future, because it can earn interest in the meantime. The present value of a future amount is found by discounting it with a discount rate. Conversely, the future value gives what an amount today grows to after $n$ years of compound interest.",
    f: [["P = \\frac{F}{(1+r)^n}", "present value of the amount $F$ in $n$ years"], ["F = P(1+r)^n", "future value of the amount $P$ today"]],
    legend: [["P", "present value (today)", "kr"], ["F", "future value", "kr"], ["r", "discount rate per year", ""], ["n", "number of years", ""]],
    ex: "10,000 kr in 14 years, discount rate 8%:\n$P = 10000/1.08^{14} \\approx 3405$ kr.",
    tip: "The further in time and the higher the rate, the smaller the present value of a future amount." } },
{ id: "rentes-rente",
  nb: { t: "Rentes rente",
    intro: "Med rentes rente beregnes renten også av tidligere opptjente renter, ikke bare av det opprinnelige beløpet. Det gir eksponentiell vekst i stedet for lineær. Tommelfingerregelen 72/rente gir et raskt anslag på hvor mange år det tar å doble et beløp.",
    f: [["F = P(1+r)^n", "sluttverdi med rentes rente"], ["n \\approx \\frac{72}{100r}", "tommelfingerregel for doblingstid ($r$ i %)"]],
    legend: [["P", "startbeløp", "kr"], ["r", "årlig rente", ""], ["n", "antall år", ""]],
    ex: "1000 kr til 10 % rente i 5 år:\n$F = 1000\\cdot 1{,}1^5 \\approx 1611$ kr.",
    tip: "72-regelen er en tommelfingerregel — for eksakt doblingstid bruk $n = \\ln 2/\\ln(1+r)$." },
  en: { t: "Compound interest",
    intro: "With compound interest, interest is also calculated on previously earned interest, not just the original amount. This gives exponential rather than linear growth. The rule of 72/rate gives a quick estimate of how many years it takes to double an amount.",
    f: [["F = P(1+r)^n", "future value with compound interest"], ["n \\approx \\frac{72}{100r}", "rule of thumb for doubling time ($r$ in %)"]],
    legend: [["P", "starting amount", "kr"], ["r", "annual interest rate", ""], ["n", "number of years", ""]],
    ex: "1000 kr at 10% interest for 5 years:\n$F = 1000\\cdot 1.1^5 \\approx 1611$ kr.",
    tip: "The rule of 72 is a rule of thumb — for the exact doubling time use $n = \\ln 2/\\ln(1+r)$." } },
{ id: "effektiv-rente",
  nb: { t: "Effektiv og nominell rente",
    intro: "Nominell rente er den oppgitte årsrenten, mens effektiv rente er den faktiske årlige renten når rentes rente innenfor året (og eventuelle gebyrer) er tatt med. Forrentes renten $m$ ganger i året, blir effektiv rente høyere enn nominell, siden renten legges til flere ganger.",
    f: [["r_{\\text{eff}} = \\left(1 + \\frac{r_{\\text{nom}}}{m}\\right)^m - 1", "effektiv rente ved $m$ forrentninger per år"]],
    legend: [["r_{\\text{nom}}", "nominell årsrente", ""], ["m", "antall forrentninger per år", ""], ["r_{\\text{eff}}", "effektiv årsrente", ""]],
    ex: "Nominell rente 5 % med månedlig forrentning ($m=12$):\n$r_{\\text{eff}} = (1 + 0{,}05/12)^{12} - 1 \\approx 5{,}12$ %.",
    tip: "Jo flere forrentninger per år, desto større blir gapet mellom nominell og effektiv rente." },
  en: { t: "Effective and nominal interest",
    intro: "Nominal interest is the stated annual rate, while effective interest is the actual annual rate once compounding within the year (and any fees) are included. If interest compounds $m$ times a year, effective interest is higher than nominal, since interest is added more often.",
    f: [["r_{\\text{eff}} = \\left(1 + \\frac{r_{\\text{nom}}}{m}\\right)^m - 1", "effective rate with $m$ compounding periods per year"]],
    legend: [["r_{\\text{nom}}", "nominal annual rate", ""], ["m", "compounding periods per year", ""], ["r_{\\text{eff}}", "effective annual rate", ""]],
    ex: "Nominal rate 5% with monthly compounding ($m=12$):\n$r_{\\text{eff}} = (1 + 0.05/12)^{12} - 1 \\approx 5.12\\%$.",
    tip: "The more compounding periods per year, the bigger the gap between nominal and effective rate." } },
{ id: "realrente",
  nb: { t: "Realrente",
    intro: "Realrenten er renten justert for inflasjon, og viser hvor mye kjøpekraften faktisk vokser. Er nominell rente lavere enn inflasjonen, blir realrenten negativ — pengene vokser i kroner, men taper kjøpekraft.",
    f: [["1 + r_{\\text{real}} = \\frac{1 + r_{\\text{nom}}}{1 + i}", "sammenhengen mellom nominell rente, inflasjon og realrente"]],
    legend: [["r_{\\text{nom}}", "nominell rente", ""], ["i", "inflasjon", ""], ["r_{\\text{real}}", "realrente", ""]],
    ex: "Nominell rente 6 %, inflasjon 2 %:\n$r_{\\text{real}} = 1{,}06/1{,}02 - 1 \\approx 3{,}92$ %.",
    tip: "En enkel tilnærming er $r_{\\text{real}} \\approx r_{\\text{nom}} - i$, men den nøyaktige formelen bruker forholdstallet." },
  en: { t: "Real interest rate",
    intro: "The real interest rate is the rate adjusted for inflation, showing how much purchasing power actually grows. If nominal interest is lower than inflation, the real rate is negative — the money grows in currency but loses purchasing power.",
    f: [["1 + r_{\\text{real}} = \\frac{1 + r_{\\text{nom}}}{1 + i}", "relation between nominal rate, inflation and real rate"]],
    legend: [["r_{\\text{nom}}", "nominal interest rate", ""], ["i", "inflation", ""], ["r_{\\text{real}}", "real interest rate", ""]],
    ex: "Nominal rate 6%, inflation 2%:\n$r_{\\text{real}} = 1.06/1.02 - 1 \\approx 3.92\\%$.",
    tip: "A simple approximation is $r_{\\text{real}} \\approx r_{\\text{nom}} - i$, but the exact formula uses the ratio." } }
]);
TOPICS("OKON", 1, [
{ id: "npv",
  nb: { t: "Netto nåverdi (NPV)",
    intro: "Netto nåverdi summerer nåverdien av alle fremtidige kontantstrømmer og trekker fra investeringen. Er NPV positiv, gir investeringen bedre avkastning enn kalkulasjonsrenten og er lønnsom. Like store årlige kontantstrømmer kan summeres raskt med annuitetsfaktoren.",
    f: [["NPV = -I_0 + \\sum_{t=1}^{n} \\frac{C_t}{(1+r)^t}", "netto nåverdi"], ["\\text{annuitetsfaktor} = \\frac{1-(1+r)^{-n}}{r}", "for like store kontantstrømmer $C$ hvert år"]],
    legend: [["I_0", "investering i dag", "kr"], ["C_t", "kontantstrøm i år $t$", "kr"], ["r", "kalkulasjonsrente", ""]],
    ex: "Investering 100 000 kr, gir 80 000 kr/år i 6 år, $r = 7$ %:\nAnnuitetsfaktor $\\approx 4{,}7665$, $NPV \\approx -100000 + 80000\\cdot 4{,}7665 \\approx 281\\,323$ kr — lønnsom.",
    tip: "NPV > 0 betyr lønnsom investering ved gitt kalkulasjonsrente; NPV < 0 betyr ikke lønnsom." },
  en: { t: "Net present value (NPV)",
    intro: "Net present value sums the present value of all future cash flows and subtracts the investment. If NPV is positive, the investment yields better than the discount rate and is profitable. Equal annual cash flows can be summed quickly with the annuity factor.",
    f: [["NPV = -I_0 + \\sum_{t=1}^{n} \\frac{C_t}{(1+r)^t}", "net present value"], ["\\text{annuity factor} = \\frac{1-(1+r)^{-n}}{r}", "for equal cash flows $C$ each year"]],
    legend: [["I_0", "investment today", "kr"], ["C_t", "cash flow in year $t$", "kr"], ["r", "discount rate", ""]],
    ex: "Investment 100,000 kr, yields 80,000 kr/year for 6 years, $r = 7\\%$:\nAnnuity factor $\\approx 4.7665$, $NPV \\approx -100000 + 80000\\cdot 4.7665 \\approx 281{,}323$ kr — profitable.",
    tip: "NPV > 0 means a profitable investment at the given discount rate; NPV < 0 means not profitable." } },
{ id: "irr",
  nb: { t: "Internrente (IRR)",
    intro: "Internrenten er den renten som gjør netto nåverdi lik null — det stedet der prosjektet akkurat dekker sin egen kalkulasjonsrente. Investeringen er lønnsom hvis IRR er høyere enn avkastningskravet.",
    f: [["-I_0 + \\sum_{t=1}^{n} \\frac{C_t}{(1+IRR)^t} = 0", "IRR løser denne ligningen"]],
    legend: [["IRR", "internrenten", ""], ["I_0", "investering i dag", "kr"], ["C_t", "kontantstrøm i år $t$", "kr"]],
    ex: "Investering 200, gir 140 etter år 1 og 140 etter år 2:\n$-200 + 140/(1+r) + 140/(1+r)^2 = 0 \\Rightarrow r \\approx 25{,}7$ %.",
    tip: "IRR finnes vanligvis ved prøving og feiling eller programvare — det finnes sjelden en enkel formel." },
  en: { t: "Internal rate of return (IRR)",
    intro: "The internal rate of return is the rate that makes net present value equal to zero — the point where the project exactly covers its own discount rate. The investment is profitable if IRR is higher than the required rate of return.",
    f: [["-I_0 + \\sum_{t=1}^{n} \\frac{C_t}{(1+IRR)^t} = 0", "IRR solves this equation"]],
    legend: [["IRR", "the internal rate of return", ""], ["I_0", "investment today", "kr"], ["C_t", "cash flow in year $t$", "kr"]],
    ex: "Investment 200, yields 140 after year 1 and 140 after year 2:\n$-200 + 140/(1+r) + 140/(1+r)^2 = 0 \\Rightarrow r \\approx 25.7\\%$.",
    tip: "IRR is usually found by trial and error or software — there is rarely a simple formula." } },
{ id: "tilbakebetalingstid",
  nb: { t: "Tilbakebetalingstid",
    intro: "Enkel tilbakebetalingstid er hvor lang tid det tar før den årlige besparelsen eller inntekten har dekket investeringen, uten å diskontere. Den er lett å regne ut, men ignorerer tidsverdien av penger og alt som skjer etter at investeringen er tilbakebetalt.",
    f: [["T = \\frac{I_0}{C}", "enkel tilbakebetalingstid ved like store årlige kontantstrømmer $C$"]],
    legend: [["I_0", "investering", "kr"], ["C", "årlig besparelse/inntekt", "kr"], ["T", "tilbakebetalingstid", "år"]],
    ex: "Maskin til 100 000 kr sparer 40 000 kr/år:\n$T = 100000/40000 = 2{,}5$ år.",
    tip: "Kort tilbakebetalingstid betyr ikke nødvendigvis høy lønnsomhet — metoden ser ikke på kontantstrømmer etterpå." },
  en: { t: "Payback period",
    intro: "Simple payback period is how long it takes before the annual savings or income has covered the investment, without discounting. It is easy to calculate, but ignores the time value of money and everything that happens after the investment is paid back.",
    f: [["T = \\frac{I_0}{C}", "simple payback period with equal annual cash flows $C$"]],
    legend: [["I_0", "investment", "kr"], ["C", "annual savings/income", "kr"], ["T", "payback period", "years"]],
    ex: "Machine costing 100,000 kr saves 40,000 kr/year:\n$T = 100000/40000 = 2.5$ years.",
    tip: "A short payback period does not necessarily mean high profitability — the method ignores cash flows afterwards." } },
{ id: "annuitet-serielan",
  nb: { t: "Annuitetslån og serielån",
    intro: "Et annuitetslån har like store terminbeløp gjennom hele løpetiden, der andelen renter synker og andelen avdrag øker over tid. Et serielån har like store avdrag, slik at terminbeløpet synker etter hvert som gjelden minker — det gir lavere totale renter enn et annuitetslån med samme rente og løpetid.",
    f: [["A = P\\,\\frac{r}{1-(1+r)^{-n}}", "terminbeløp i et annuitetslån"]],
    legend: [["P", "lånebeløp", "kr"], ["r", "rente per termin", ""], ["n", "antall terminer", ""], ["A", "terminbeløp (annuitet)", "kr"]],
    ex: "Lån 500 000 kr, 3 % rente, 10 år:\n$A = 500000\\cdot \\dfrac{0{,}03}{1-1{,}03^{-10}} \\approx 58\\,615$ kr per år.",
    tip: "Annuitetslån gir forutsigbare terminbeløp, serielån gir lavest total rentekostnad." },
  en: { t: "Annuity and serial loans",
    intro: "An annuity loan has equal instalments through the whole term, where the interest portion decreases and the principal portion increases over time. A serial loan has equal principal payments, so the instalment shrinks as the debt decreases — giving lower total interest than an annuity loan with the same rate and term.",
    f: [["A = P\\,\\frac{r}{1-(1+r)^{-n}}", "instalment in an annuity loan"]],
    legend: [["P", "loan amount", "kr"], ["r", "rate per period", ""], ["n", "number of periods", ""], ["A", "instalment (annuity payment)", "kr"]],
    ex: "Loan 500,000 kr, 3% interest, 10 years:\n$A = 500000\\cdot \\dfrac{0.03}{1-1.03^{-10}} \\approx 58{,}615$ kr per year.",
    tip: "Annuity loans give predictable instalments, serial loans give the lowest total interest cost." } }
]);
TOPICS("OKON", 2, [
{ id: "faste-variable-kostnader",
  nb: { t: "Faste og variable kostnader",
    intro: "Faste kostnader, som husleie, endres ikke med produsert mengde. Variable kostnader, som råvarer, øker med antall enheter produsert. Sammen gir de totalkostnaden, og gjennomsnittskostnaden per enhet synker når faste kostnader fordeles på flere enheter.",
    f: [["TK = FK + VK\\cdot Q", "totalkostnad"], ["\\bar{K} = \\frac{FK + VK\\cdot Q}{Q}", "gjennomsnittskostnad per enhet"]],
    legend: [["FK", "faste kostnader", "kr"], ["VK", "variabel kostnad per enhet", "kr"], ["Q", "produsert mengde", "stk"]],
    ex: "$FK = 20\\,000$ kr, $VK = 50$ kr/stk, $Q = 2000$:\n$\\bar K = (20000 + 50\\cdot 2000)/2000 = 60$ kr per stk.",
    tip: "Skalafordeler kommer nettopp av at faste kostnader fordeles på flere enheter når volumet øker." },
  en: { t: "Fixed and variable costs",
    intro: "Fixed costs, like rent, do not change with the quantity produced. Variable costs, like raw materials, increase with the number of units produced. Together they give total cost, and the average cost per unit falls as fixed costs are spread over more units.",
    f: [["TC = FC + VC\\cdot Q", "total cost"], ["\\bar{C} = \\frac{FC + VC\\cdot Q}{Q}", "average cost per unit"]],
    legend: [["FC", "fixed costs", "kr"], ["VC", "variable cost per unit", "kr"], ["Q", "quantity produced", "units"]],
    ex: "$FC = 20{,}000$ kr, $VC = 50$ kr/unit, $Q = 2000$:\n$\\bar C = (20000 + 50\\cdot 2000)/2000 = 60$ kr per unit.",
    tip: "Economies of scale come precisely from fixed costs being spread over more units as volume increases." } },
{ id: "dekningsbidrag-nullpunkt",
  nb: { t: "Dekningsbidrag og nullpunktsomsetning",
    intro: "Dekningsbidraget per enhet er prisen minus variabel kostnad per enhet — det som er igjen til å dekke faste kostnader og gi overskudd. Nullpunktet (break-even) er antall enheter der dekningsbidraget akkurat dekker de faste kostnadene, altså der bedriften verken taper eller tjener.",
    f: [["DB = p - VK", "dekningsbidrag per enhet"], ["Q_0 = \\frac{FK}{p - VK}", "nullpunktsmengde"]],
    legend: [["p", "salgspris per enhet", "kr"], ["VK", "variabel kostnad per enhet", "kr"], ["FK", "faste kostnader", "kr"], ["Q_0", "nullpunktsmengde", "stk"]],
    ex: "$FK = 50\\,000$ kr, $p = 500$ kr, $VK = 250$ kr:\n$Q_0 = 50000/(500-250) = 200$ stk.",
    tip: "Under nullpunktsmengden taper bedriften penger, over den tjener den — selv med samme pris og kostnader." },
  en: { t: "Contribution margin and break-even",
    intro: "The contribution margin per unit is the price minus variable cost per unit — what is left to cover fixed costs and generate profit. Break-even is the number of units where the contribution margin exactly covers fixed costs, i.e. where the business neither loses nor gains.",
    f: [["CM = p - VC", "contribution margin per unit"], ["Q_0 = \\frac{FC}{p - VC}", "break-even quantity"]],
    legend: [["p", "selling price per unit", "kr"], ["VC", "variable cost per unit", "kr"], ["FC", "fixed costs", "kr"], ["Q_0", "break-even quantity", "units"]],
    ex: "$FC = 50{,}000$ kr, $p = 500$ kr, $VC = 250$ kr:\n$Q_0 = 50000/(500-250) = 200$ units.",
    tip: "Below break-even quantity the business loses money, above it profits — even with the same price and costs." } },
{ id: "linear-avskrivning",
  nb: { t: "Lineær avskrivning",
    intro: "Lineær avskrivning fordeler verditapet på en eiendel jevnt over levetiden, slik at samme beløp trekkes fra bokført verdi hvert år. Den bygger på investeringskostnaden minus forventet restverdi ved slutten av levetiden.",
    f: [["D = \\frac{I - R}{n}", "årlig avskrivning"]],
    legend: [["I", "investeringskostnad", "kr"], ["R", "restverdi ved slutt av levetiden", "kr"], ["n", "levetid", "år"], ["D", "årlig avskrivning", "kr"]],
    ex: "Maskin til 100 000 kr, restverdi 50 000 kr, levetid 4 år:\n$D = (100000 - 50000)/4 = 12\\,500$ kr per år.",
    tip: "Lineær avskrivning gir samme beløp hvert år — den er forskjellig fra saldoavskrivning, som avskriver en prosentandel av gjenværende verdi." },
  en: { t: "Straight-line depreciation",
    intro: "Straight-line depreciation spreads the loss in value of an asset evenly over its lifetime, so the same amount is deducted from book value each year. It is based on the investment cost minus the expected residual value at the end of its life.",
    f: [["D = \\frac{I - R}{n}", "annual depreciation"]],
    legend: [["I", "investment cost", "kr"], ["R", "residual value at end of life", "kr"], ["n", "useful life", "years"], ["D", "annual depreciation", "kr"]],
    ex: "Machine costing 100,000 kr, residual value 50,000 kr, life 4 years:\n$D = (100000 - 50000)/4 = 12{,}500$ kr per year.",
    tip: "Straight-line depreciation gives the same amount each year — unlike declining-balance depreciation, which deducts a percentage of the remaining value." } },
{ id: "alternativkostnad-sunk-cost",
  nb: { t: "Alternativkostnad og sunk cost",
    intro: "Alternativkostnaden er verdien av det beste alternativet man gir opp ved å velge noe annet, og bør telle med i beslutninger selv om den ikke står i regnskapet. Sunk cost (sokkekostnad) er kostnader som allerede er påløpt og ikke kan hentes inn, og som derfor ikke skal påvirke fremtidige beslutninger.",
    f: [["\\text{Alternativkostnad} = \\text{verdien av beste alternativ}", "tas med i beslutningen"], ["\\text{Sunk cost} \\to \\text{ignoreres i nye beslutninger}", "påløpte, ikke-gjenvinnbare kostnader"]],
    legend: [],
    ex: "Har man brukt 2 mill. kr på et prosjekt som ikke lenger er lønnsomt, skal ikke de 2 mill. kr avgjøre om man fortsetter — bare fremtidige kontantstrømmer teller.",
    tip: "«Vi har allerede brukt så mye penger» er et klassisk sunk cost-feilgrep — det som er brukt, er brukt." },
  en: { t: "Opportunity cost and sunk cost",
    intro: "Opportunity cost is the value of the best alternative given up by choosing something else, and should count in decisions even though it does not appear in the accounts. Sunk cost is expenditure already incurred and unrecoverable, and should therefore not influence future decisions.",
    f: [["\\text{Opportunity cost} = \\text{value of best alternative}", "included in the decision"], ["\\text{Sunk cost} \\to \\text{ignored in new decisions}", "incurred, unrecoverable costs"]],
    legend: [],
    ex: "If 2 million kr has been spent on a project that is no longer profitable, that 2 million kr should not decide whether to continue — only future cash flows count.",
    tip: "\"We've already spent so much\" is a classic sunk-cost fallacy — what is spent is spent." } }
]);
// ---------------- PROD: Produktutvikling ----------------
TOPICS("PROD", 0, [
{ id: "utviklingsprosessen",
  nb: { t: "Produktutviklingsprosessen",
    intro: "En typisk produktutviklingsprosess (Ulrich & Eppinger) går gjennom planlegging, konseptutvikling, systemdesign, detaljdesign, testing og produksjonsoppstart. Prosessen deles ofte i faser med beslutningspunkter, gates, mellom hver fase, der man bestemmer om man skal fortsette, stoppe eller gjøre om.",
    f: [["\\text{planlegging} \\to \\text{konsept} \\to \\text{system} \\to \\text{detalj} \\to \\text{test} \\to \\text{produksjon}", "typisk faserekkefølge"]],
    legend: [],
    ex: "Ved hver gate i et stage-gate-system tas en av tre beslutninger: fortsett, stopp, eller gjør om og prøv igjen.",
    tip: "Jo tidligere en feil oppdages i prosessen, desto billigere er den å rette opp." },
  en: { t: "Product development process",
    intro: "A typical product development process (Ulrich & Eppinger) moves through planning, concept development, system-level design, detail design, testing, and production ramp-up. The process is often divided into phases with decision points, gates, between each, where the team decides whether to continue, stop, or rework.",
    f: [["\\text{planning} \\to \\text{concept} \\to \\text{system} \\to \\text{detail} \\to \\text{test} \\to \\text{production}", "typical phase order"]],
    legend: [],
    ex: "At each gate in a stage-gate system, one of three decisions is made: go, kill, or rework and retry.",
    tip: "The earlier a flaw is caught in the process, the cheaper it is to fix." } },
{ id: "behov-og-spesifikasjon",
  nb: { t: "Kundebehov og spesifikasjon",
    intro: "Et kundebehov er uttrykt på kundens eget språk, som «lett å bære», mens en spesifikasjon oversetter det til en målbar størrelse med enhet og målverdi, som «masse under 1,2 kg». Kravspesifikasjonen samler alle slike målbare krav og brukes til å vurdere konsepter og verifisere det ferdige produktet.",
    f: [["\\text{behov (kundens språk)} \\to \\text{spesifikasjon (målbar, med enhet)}", "oversettelsen fra behov til krav"]],
    legend: [],
    ex: "Behovet «produktet må tåle fall» kan bli spesifikasjonen: «tåler fall fra 1,5 m på betong uten funksjonsfeil».",
    tip: "En god spesifikasjon kan verifiseres med en måling eller test — ikke bare vurderes subjektivt." },
  en: { t: "Customer needs and specifications",
    intro: "A customer need is expressed in the customer's own words, like \"easy to carry\", while a specification translates it into a measurable quantity with a unit and target value, like \"mass under 1.2 kg\". The requirements specification collects all such measurable requirements and is used to evaluate concepts and verify the finished product.",
    f: [["\\text{need (customer's words)} \\to \\text{specification (measurable, with unit)}", "translating a need into a requirement"]],
    legend: [],
    ex: "The need \"the product must survive a drop\" can become the specification: \"survives a 1.5 m drop onto concrete without functional failure\".",
    tip: "A good specification can be verified with a measurement or test — not just judged subjectively." } },
{ id: "house-of-quality",
  nb: { t: "House of Quality (QFD)",
    intro: "House of Quality er hovedverktøyet i Quality Function Deployment (QFD), og viser sammenhengen mellom kundebehov og tekniske egenskaper i en matrise. «Taket» over matrisen viser hvordan de tekniske egenskapene påvirker hverandre, slik at man ser avveininger tidlig.",
    f: [["\\text{kundebehov} \\times \\text{tekniske egenskaper}", "hovedmatrisen i House of Quality"]],
    legend: [],
    ex: "Kundebehovet «stille i bruk» kobles til den tekniske egenskapen «støynivå i dB», og relasjonen vektes i matrisen.",
    tip: "Bruk House of Quality tidlig for å sikre at tekniske spesifikasjoner faktisk henger sammen med det kundene bryr seg om." },
  en: { t: "House of Quality (QFD)",
    intro: "The House of Quality is the main tool in Quality Function Deployment (QFD), showing the relationship between customer needs and technical characteristics in a matrix. The \"roof\" above the matrix shows how the technical characteristics affect each other, revealing trade-offs early.",
    f: [["\\text{customer needs} \\times \\text{technical characteristics}", "the main matrix in the House of Quality"]],
    legend: [],
    ex: "The customer need \"quiet in use\" is linked to the technical characteristic \"noise level in dB\", and the relationship is weighted in the matrix.",
    tip: "Use the House of Quality early to make sure technical specifications actually connect to what customers care about." } },
{ id: "parvis-sammenligning",
  nb: { t: "Parvis sammenligning",
    intro: "For å rangere en liste med kundebehov kan man sammenligne dem parvis, to og to, og telle hvor mange ganger hvert behov «vinner». Antall sammenligninger som trengs for $n$ behov er gitt av binomialkoeffisienten $\\binom{n}{2}$, siden hvert par vurderes én gang.",
    f: [["\\binom{n}{2} = \\frac{n(n-1)}{2}", "antall parvise sammenligninger for $n$ elementer"]],
    legend: [["n", "antall kundebehov som rangeres", ""]],
    ex: "For 6 kundebehov trengs $\\binom{6}{2} = \\dfrac{6\\cdot 5}{2} = 15$ sammenligninger.",
    tip: "Metoden vokser raskt: dobler du antall behov, mer enn dobler du antall sammenligninger." },
  en: { t: "Pairwise comparison",
    intro: "To rank a list of customer needs, they can be compared two at a time, counting how many times each need \"wins\". The number of comparisons needed for $n$ needs is given by the binomial coefficient $\\binom{n}{2}$, since each pair is judged once.",
    f: [["\\binom{n}{2} = \\frac{n(n-1)}{2}", "number of pairwise comparisons for $n$ items"]],
    legend: [["n", "number of customer needs being ranked", ""]],
    ex: "For 6 customer needs, $\\binom{6}{2} = \\dfrac{6\\cdot 5}{2} = 15$ comparisons are needed.",
    tip: "The method grows quickly: doubling the number of needs more than doubles the number of comparisons." } }
]);
TOPICS("PROD", 1, [
{ id: "morfologisk-matrise",
  nb: { t: "Morfologisk matrise",
    intro: "En morfologisk matrise lister delfunksjoner produktet må løse, og mulige løsninger for hver av dem. Man genererer konsepter systematisk ved å kombinere én løsning fra hver rad. Antall teoretisk mulige konsepter er produktet av antall alternativer for hver delfunksjon.",
    f: [["N_{\\text{konsepter}} = \\prod_i k_i", "totalt antall kombinasjoner"]],
    legend: [["k_i", "antall løsningsalternativer for delfunksjon $i$", ""]],
    ex: "5 delfunksjoner med 4, 5, 3, 3 og 5 alternativer:\n$4\\cdot 5\\cdot 3\\cdot 3\\cdot 5 = 900$ mulige konsepter.",
    tip: "De fleste kombinasjonene fra en morfologisk matrise er urealistiske — den brukes til å utforske bredden, ikke til å lage alle 900." },
  en: { t: "Morphological matrix",
    intro: "A morphological matrix lists the sub-functions a product must solve, and possible solutions for each. Concepts are generated systematically by combining one solution from each row. The theoretical number of possible concepts is the product of the number of alternatives for each sub-function.",
    f: [["N_{\\text{concepts}} = \\prod_i k_i", "total number of combinations"]],
    legend: [["k_i", "number of solution alternatives for sub-function $i$", ""]],
    ex: "5 sub-functions with 4, 5, 3, 3 and 5 alternatives:\n$4\\cdot 5\\cdot 3\\cdot 3\\cdot 5 = 900$ possible concepts.",
    tip: "Most combinations from a morphological matrix are unrealistic — it is used to explore breadth, not to build all 900." } },
{ id: "pugh-matrise",
  nb: { t: "Pugh-matrise (konseptscreening)",
    intro: "En Pugh-matrise sammenligner flere konsepter mot et referansekonsept på hvert kriterium, med pluss (bedre), null (likt) eller minus (dårligere). Nettoscoren er antall pluss minus antall minus, og brukes til å luke ut svake konsepter tidlig, før en mer detaljert vektet vurdering.",
    f: [["\\text{netto} = (\\text{antall } +) - (\\text{antall } -)", "nettoscore i konseptscreening"]],
    legend: [],
    ex: "Et konsept får 5 pluss, 4 nuller og 1 minus:\nNettoscore $= 5 - 1 = 4$.",
    tip: "Nullene teller ikke i nettoscoren, men viser hvor konseptet er likeverdig med referansen." },
  en: { t: "Pugh matrix (concept screening)",
    intro: "A Pugh matrix compares several concepts against a reference concept on each criterion, with plus (better), zero (same) or minus (worse). The net score is the number of pluses minus the number of minuses, and is used to weed out weak concepts early, before a more detailed weighted evaluation.",
    f: [["\\text{net} = (\\text{number of } +) - (\\text{number of } -)", "net score in concept screening"]],
    legend: [],
    ex: "A concept gets 5 pluses, 4 zeros and 1 minus:\nNet score $= 5 - 1 = 4$.",
    tip: "The zeros do not count in the net score, but show where the concept is equal to the reference." } },
{ id: "vektet-konseptscoring",
  nb: { t: "Vektet konseptscoring",
    intro: "Vektet konseptscoring bygger videre på Pugh-metoden ved å gi hvert kriterium en vekt etter viktighet, og hvert konsept en poengsum på hvert kriterium. Totalscoren er summen av vekt ganger poeng, og gir et mer nyansert grunnlag for å velge konsept enn en enkel netto-telling.",
    f: [["S = \\sum_i w_i\\,s_i", "vektet totalscore"]],
    legend: [["w_i", "vekt for kriterium $i$ (summerer til 1)", ""], ["s_i", "poengsum konseptet får på kriterium $i$", ""]],
    ex: "Poeng 3, 4, 5, 4 med vekter 0,4, 0,3, 0,2, 0,1:\n$S = 0{,}4\\cdot3 + 0{,}3\\cdot4 + 0{,}2\\cdot5 + 0{,}1\\cdot4 = 3{,}8$.",
    tip: "Vektene bør reflektere kundens prioriteringer, ikke utviklerens egen smak." },
  en: { t: "Weighted concept scoring",
    intro: "Weighted concept scoring builds on the Pugh method by giving each criterion a weight by importance, and each concept a score on each criterion. The total score is the sum of weight times score, giving a more nuanced basis for choosing a concept than a simple net count.",
    f: [["S = \\sum_i w_i\\,s_i", "weighted total score"]],
    legend: [["w_i", "weight of criterion $i$ (sums to 1)", ""], ["s_i", "score the concept gets on criterion $i$", ""]],
    ex: "Scores 3, 4, 5, 4 with weights 0.4, 0.3, 0.2, 0.1:\n$S = 0.4\\cdot3 + 0.3\\cdot4 + 0.2\\cdot5 + 0.1\\cdot4 = 3.8$.",
    tip: "The weights should reflect the customer's priorities, not the developer's own taste." } },
{ id: "prototyping-og-idemyldring",
  nb: { t: "Idémyldring og prototyping",
    intro: "I idémyldring (brainstorming) er hovedregelen å ikke kritisere ideer underveis og gå for mengde — vurderingen kommer i en senere fase. Man bør utvikle flere konsepter før man velger, for å utforske løsningsrommet og unngå å låse seg for tidlig. En «looks-like»-prototyp viser formen, mens en «works-like» (funksjonell) prototyp tester om løsningen virker.",
    f: [["\\text{«looks-like»} \\neq \\text{«works-like»}", "utseende og funksjon testes ofte hver for seg"]],
    legend: [],
    ex: "En skumplastmodell viser hvordan produktet ser ut og føles i hånden (looks-like), mens en enkel elektronikkrigg tester om kretsen fungerer (works-like).",
    tip: "Det første konseptet man kommer på er sjelden det beste — bredde tidlig gir bedre valg senere." },
  en: { t: "Brainstorming and prototyping",
    intro: "In brainstorming, the main rule is not to criticize ideas as they come and to aim for quantity — evaluation comes in a later phase. Several concepts should be developed before choosing, to explore the solution space and avoid locking in too early. A \"looks-like\" prototype shows the form, while a \"works-like\" (functional) prototype tests whether the solution works.",
    f: [["\\text{``looks-like''} \\neq \\text{``works-like''}", "appearance and function are often tested separately"]],
    legend: [],
    ex: "A foam model shows how the product looks and feels in the hand (looks-like), while a simple electronics rig tests whether the circuit works (works-like).",
    tip: "The first concept you think of is rarely the best — early breadth leads to better choices later." } }
]);
TOPICS("PROD", 2, [
{ id: "dfa",
  nb: { t: "DFA – Design for Assembly",
    intro: "DFA (Design for Assembly) handler om å designe produkter med færre deler og enklere montasje. For hver del spør man om den virkelig må være en egen del, eller om den kan slås sammen med en annen. Færre deler betyr kortere monteringstid og lavere kostnad.",
    f: [["\\Delta t = (n_{\\text{før}} - n_{\\text{etter}})\\cdot t_{\\text{del}}", "spart monteringstid ved å redusere antall deler"]],
    legend: [["n_{\\text{før}},\\ n_{\\text{etter}}", "antall deler før og etter DFA", ""], ["t_{\\text{del}}", "monteringstid per del", "s"]],
    ex: "En DFA-analyse reduserer antall deler fra 16 til 6, med 20 s per del:\n$\\Delta t = (16-6)\\cdot 20 = 200$ s spart per produkt.",
    tip: "Still spørsmålet «må denne delen være separat?» for hver del — det er kjernen i DFA." },
  en: { t: "DFA – Design for Assembly",
    intro: "DFA (Design for Assembly) is about designing products with fewer parts and simpler assembly. For each part, ask whether it truly needs to be a separate piece, or could be merged with another. Fewer parts means shorter assembly time and lower cost.",
    f: [["\\Delta t = (n_{\\text{before}} - n_{\\text{after}})\\cdot t_{\\text{part}}", "assembly time saved by reducing part count"]],
    legend: [["n_{\\text{before}},\\ n_{\\text{after}}", "number of parts before and after DFA", ""], ["t_{\\text{part}}", "assembly time per part", "s"]],
    ex: "A DFA analysis reduces the part count from 16 to 6, at 20 s per part:\n$\\Delta t = (16-6)\\cdot 20 = 200$ s saved per product.",
    tip: "Ask \"does this part need to be separate?\" for every part — that is the core of DFA." } },
{ id: "dfm-sproytestoping",
  nb: { t: "DFM og sprøytestøping",
    intro: "DFM (Design for Manufacturing) handler om å utforme deler slik at de er enkle og billige å produsere. For sprøytestøpte deler betyr det gjerne jevn godstykkelse, som unngår synkemerker og indre spenninger fordi tykke partier kjøles saktere, og slippvinkel (typisk 0,5–2°) slik at delen løsner lett fra formen.",
    f: [["\\text{jevn godstykkelse} + \\text{slippvinkel } 0{,}5\\text{–}2^\\circ", "to grunnregler for sprøytestøpte deler"]],
    legend: [],
    ex: "En vegg med varierende tykkelse kan gi synkemerker der den er tykkest — løsningen er å holde godstykkelsen så jevn som mulig.",
    tip: "Sett stramme toleranser bare der funksjonen faktisk krever det — strammere toleranser gir høyere kostnad." },
  en: { t: "DFM and injection molding",
    intro: "DFM (Design for Manufacturing) is about shaping parts so they are simple and cheap to produce. For injection-molded parts this usually means uniform wall thickness, which avoids sink marks and internal stresses since thick sections cool more slowly, and a draft angle (typically 0.5–2°) so the part releases easily from the mold.",
    f: [["\\text{uniform wall thickness} + \\text{draft angle } 0.5\\text{–}2^\\circ", "two basic rules for injection-molded parts"]],
    legend: [],
    ex: "A wall with varying thickness can get sink marks where it is thickest — the fix is to keep the wall thickness as uniform as possible.",
    tip: "Set tight tolerances only where function actually requires it — tighter tolerances mean higher cost." } },
{ id: "break-even-produksjonsmetode",
  nb: { t: "Break-even mellom produksjonsmetoder",
    intro: "Ulike produksjonsmetoder har ulik kostnadsstruktur: 3D-printing har lav eller ingen oppstartskostnad, men høy kostnad per del, mens sprøytestøping har en dyr form som fast kostnad, men lav kostnad per del. Break-even-mengden er der de to metodene koster akkurat det samme.",
    f: [["Q_0\\cdot k_1 = F_2 + Q_0\\cdot k_2", "totalkostnaden er lik ved break-even-mengden $Q_0$"]],
    legend: [["k_1", "kostnad per del, metode uten fast kostnad (f.eks. 3D-print)", "kr"], ["F_2", "fast kostnad for metode 2 (f.eks. form)", "kr"], ["k_2", "kostnad per del, metode 2", "kr"]],
    ex: "3D-print 100 kr/stk. Sprøytestøping: form 20 000 kr + 10 kr/stk.\n$100Q = 20000 + 10Q \\Rightarrow Q = 20000/90 \\approx 222$ stk.",
    tip: "Under break-even-mengden er metoden med lav fast kostnad billigst, over den er det motsatt." },
  en: { t: "Break-even between production methods",
    intro: "Different production methods have different cost structures: 3D printing has low or no start-up cost but high cost per part, while injection molding has an expensive mold as a fixed cost but low cost per part. The break-even quantity is where the two methods cost exactly the same.",
    f: [["Q_0\\cdot k_1 = F_2 + Q_0\\cdot k_2", "total cost is equal at the break-even quantity $Q_0$"]],
    legend: [["k_1", "cost per part, method with no fixed cost (e.g. 3D printing)", "kr"], ["F_2", "fixed cost of method 2 (e.g. mold)", "kr"], ["k_2", "cost per part, method 2", "kr"]],
    ex: "3D printing 100 kr/unit. Injection molding: mold 20,000 kr + 10 kr/unit.\n$100Q = 20000 + 10Q \\Rightarrow Q = 20000/90 \\approx 222$ units.",
    tip: "Below the break-even quantity, the method with low fixed cost is cheapest; above it, the opposite is true." } },
{ id: "materialkostnad",
  nb: { t: "Materialkostnad fra volum og tetthet",
    intro: "Materialkostnaden for en del kan regnes ut fra volumet, materialets tetthet og prisen per kilo. Først finner man massen ved å gange volum med tetthet, deretter ganges massen med prisen per kilo.",
    f: [["m = V\\cdot \\rho", "masse fra volum og tetthet"], ["K = m\\cdot p_{\\text{kg}}", "materialkostnad"]],
    legend: [["V", "volum", "cm³"], ["\\rho", "tetthet", "g/cm³"], ["m", "masse", "g"], ["p_{\\text{kg}}", "pris per kg", "kr/kg"]],
    ex: "Del på 100 cm³ i stål ($\\rho = 7{,}85$ g/cm³), pris 20 kr/kg:\n$m = 100\\cdot 7{,}85 = 785$ g, $K = 0{,}785\\cdot 20 \\approx 15{,}7$ kr.",
    tip: "Husk å regne om fra gram til kilo før du ganger med prisen per kilo." },
  en: { t: "Material cost from volume and density",
    intro: "The material cost of a part can be found from its volume, the material's density, and the price per kilogram. First find the mass by multiplying volume by density, then multiply the mass by the price per kilogram.",
    f: [["m = V\\cdot \\rho", "mass from volume and density"], ["K = m\\cdot p_{\\text{kg}}", "material cost"]],
    legend: [["V", "volume", "cm³"], ["\\rho", "density", "g/cm³"], ["m", "mass", "g"], ["p_{\\text{kg}}", "price per kg", "kr/kg"]],
    ex: "Part of 100 cm³ in steel ($\\rho = 7.85$ g/cm³), price 20 kr/kg:\n$m = 100\\cdot 7.85 = 785$ g, $K = 0.785\\cdot 20 \\approx 15.7$ kr.",
    tip: "Remember to convert from grams to kilograms before multiplying by the price per kilogram." } },
{ id: "lca-livslopsvurdering",
  nb: { t: "Livsløpsvurdering (LCA)",
    intro: "En livsløpsvurdering (LCA) ser på et produkts miljøpåvirkning gjennom hele livsløpet: råvareuttak, produksjon, transport, bruk og avhending. Den brukes til å sammenligne materialer eller design opp mot hverandre, med hensyn til blant annet energiforbruk, CO₂-utslipp og gjenvinning.",
    f: [["\\text{råvarer} \\to \\text{produksjon} \\to \\text{transport} \\to \\text{bruk} \\to \\text{avhending}", "fasene i en livsløpsvurdering"]],
    legend: [],
    ex: "Et produkt kan ha lavt CO₂-utslipp i produksjon, men høyt i brukfasen hvis det bruker mye strøm — LCA fanger opp begge deler.",
    tip: "En vurdering som bare ser på produksjonsfasen, kan gi feil konklusjon om det totale miljøavtrykket." },
  en: { t: "Life cycle assessment (LCA)",
    intro: "A life cycle assessment (LCA) looks at a product's environmental impact across its whole life cycle: raw material extraction, production, transport, use and disposal. It is used to compare materials or designs against each other, considering things like energy use, CO2 emissions and recyclability.",
    f: [["\\text{raw materials} \\to \\text{production} \\to \\text{transport} \\to \\text{use} \\to \\text{disposal}", "the phases of a life cycle assessment"]],
    legend: [],
    ex: "A product can have low CO2 emissions in production but high emissions in the use phase if it consumes a lot of electricity — LCA captures both.",
    tip: "An assessment that only looks at the production phase can give a wrong conclusion about the total environmental footprint." } }
]);
// ---------------- STKD6610: Teknologi, etikk og bærekraft ----------------
TOPICS("STKD6610", 0, [
{ id: "livslopsanalyse",
  nb: { t: "Livsløpsanalyse (LCA)",
    intro: "En livsløpsanalyse (LCA) vurderer miljøbelastningen til et produkt «fra vugge til grav»: råvareuttak, produksjon, transport, bruk og avfallshåndtering. For at sammenligninger skal være rettferdige, må man regne per felles funksjonell enhet, som «1 km transport».",
    f: [["\\text{LCA: vugge} \\to \\text{grav}", "råvarer, produksjon, transport, bruk, avhending"]],
    legend: [["\\text{funksjonell enhet}", "det man sammenligner per, felles for alle alternativer", ""]],
    ex: "To emballasjetyper kan sammenlignes per «1000 pakkede liter melk», ikke per kilo emballasje alene — ellers blir sammenligningen skjev.",
    tip: "Uten en felles funksjonell enhet blir sammenligning mellom produkter meningsløs." },
  en: { t: "Life cycle assessment (LCA)",
    intro: "A life cycle assessment (LCA) evaluates a product's environmental impact \"from cradle to grave\": raw material extraction, production, transport, use and waste handling. For comparisons to be fair, results must be calculated per a shared functional unit, such as \"1 km of transport\".",
    f: [["\\text{LCA: cradle} \\to \\text{grave}", "raw materials, production, transport, use, disposal"]],
    legend: [["\\text{functional unit}", "what is compared per, shared across alternatives", ""]],
    ex: "Two packaging types can be compared per \"1000 litres of milk packaged\", not per kilogram of packaging alone — otherwise the comparison is skewed.",
    tip: "Without a shared functional unit, comparing products becomes meaningless." } },
{ id: "sirkular-okonomi",
  nb: { t: "Sirkulær økonomi",
    intro: "Sirkulær økonomi handler om å holde materialer og produkter i bruk så lenge som mulig, gjennom reparasjon, ombruk, gjenvinning og design for demontering. Ombruk bruker produktet igjen som det er og ligger høyere i avfallshierarkiet enn resirkulering, som bryter det ned til råmateriale.",
    f: [["\\text{ombruk} > \\text{resirkulering}", "avfallshierarkiet: ombruk foretrekkes fremfor materialgjenvinning"]],
    legend: [],
    ex: "Skrueforbindelser i stedet for liming er design for demontering: det gjør det mulig å skille materialer for reparasjon eller gjenvinning senere.",
    tip: "Spør «kan dette brukes igjen som det er» før du tenker resirkulering — ombruk sparer mer ressurser." },
  en: { t: "Circular economy",
    intro: "A circular economy is about keeping materials and products in use for as long as possible, through repair, reuse, recycling and design for disassembly. Reuse uses the product again as it is and ranks higher in the waste hierarchy than recycling, which breaks it down into raw material.",
    f: [["\\text{reuse} > \\text{recycling}", "the waste hierarchy: reuse is preferred over material recycling"]],
    legend: [],
    ex: "Screw joints instead of gluing is design for disassembly: it allows materials to be separated for repair or recycling later.",
    tip: "Ask \"can this be used again as is\" before thinking recycling — reuse saves more resources." } },
{ id: "klimagassregnskap",
  nb: { t: "Klimagassregnskap og scope 1–3",
    intro: "Et klimagassregnskap måler klimagassutslipp i CO₂-ekvivalenter, der alle klimagasser regnes om til den mengden CO₂ som gir samme oppvarmingseffekt. Utslipp deles i scope 1 (direkte, egne kilder), scope 2 (kjøpt energi) og scope 3 (resten av verdikjeden, både oppstrøms og nedstrøms).",
    f: [["\\text{scope 1} + \\text{scope 2} + \\text{scope 3} = \\text{totalt karbonfotavtrykk}", "de tre utslippskategoriene"]],
    legend: [],
    ex: "For en bilprodusent er drivstoff i egen fabrikk scope 1, innkjøpt strøm scope 2, og utslipp fra bilenes bruksfase hos kundene scope 3.",
    tip: "Scope 3 er ofte den klart største og vanskeligste kategorien å måle nøyaktig." },
  en: { t: "Greenhouse gas accounting and scope 1–3",
    intro: "A greenhouse gas inventory measures emissions in CO2-equivalents, where all greenhouse gases are converted to the amount of CO2 that gives the same warming effect. Emissions are split into scope 1 (direct, own sources), scope 2 (purchased energy), and scope 3 (the rest of the value chain, both upstream and downstream).",
    f: [["\\text{scope 1} + \\text{scope 2} + \\text{scope 3} = \\text{total carbon footprint}", "the three emission categories"]],
    legend: [],
    ex: "For a car manufacturer, fuel at their own factory is scope 1, purchased electricity is scope 2, and emissions from cars' use phase at customers is scope 3.",
    tip: "Scope 3 is often by far the largest and hardest category to measure accurately." } },
{ id: "baerekraftsrapportering",
  nb: { t: "Bunnlinje, EPD og grønnvasking",
    intro: "Det tredelte bunnlinjeprinsippet (triple bottom line) vurderer en virksomhet etter økonomiske, sosiale og miljømessige resultater — «people, planet, profit». En miljødeklarasjon (EPD) er et standardisert dokument med livsløpsdata for et produkt, mens grønnvasking er å gi et misvisende inntrykk av at noe er miljøvennlig.",
    f: [["\\text{people} + \\text{planet} + \\text{profit}", "de tre dimensjonene i triple bottom line"]],
    legend: [],
    ex: "En bedrift som reklamerer med «miljøvennlig» uten dokumentasjon, mens produktet faktisk har høyt klimaavtrykk, driver grønnvasking.",
    tip: "En EPD gir etterprøvbare tall — en generell miljøpåstand i markedsføring gjør det ikke." },
  en: { t: "Triple bottom line, EPD and greenwashing",
    intro: "The triple bottom line evaluates a business by economic, social and environmental results — \"people, planet, profit\". An Environmental Product Declaration (EPD) is a standardized document with life cycle data for a product, while greenwashing is giving a misleading impression that something is environmentally friendly.",
    f: [["\\text{people} + \\text{planet} + \\text{profit}", "the three dimensions of the triple bottom line"]],
    legend: [],
    ex: "A company advertising \"eco-friendly\" without documentation, while the product actually has a high climate footprint, is greenwashing.",
    tip: "An EPD gives verifiable numbers — a general environmental claim in marketing does not." } }
]);
TOPICS("STKD6610", 1, [
{ id: "etiske-teorier",
  nb: { t: "Konsekvensetikk, pliktetikk og dydsetikk",
    intro: "Konsekvensetikk (som utilitarisme) vurderer en handling ut fra resultatene den fører til. Pliktetikk (som Kants kategoriske imperativ) vurderer om handlingen følger en moralsk plikt eller regel, uansett utfall. Dydsetikk, som går tilbake til Aristoteles, legger vekt på hvilken karakter en god person har.",
    f: [["\\text{konsekvens: resultat} \\ \\ \\text{plikt: regel} \\ \\ \\text{dyd: karakter}", "de tre klassiske etiske perspektivene"]],
    legend: [],
    ex: "Å bryte et løfte for å redde flere liv kan forsvares konsekvensetisk, men fordømmes pliktetisk hvis løftebrudd anses som galt uansett utfall.",
    tip: "Bruk flere etiske perspektiver på samme sak — de gir ofte ulike, utfyllende svar." },
  en: { t: "Three ethical theories",
    intro: "Consequentialism (like utilitarianism) evaluates an action by the results it leads to. Deontology (like Kant's categorical imperative) evaluates whether the action follows a moral duty or rule, regardless of outcome. Virtue ethics, going back to Aristotle, emphasizes what character a good person has.",
    f: [["\\text{consequence: outcome} \\ \\ \\text{duty: rule} \\ \\ \\text{virtue: character}", "the three classic ethical perspectives"]],
    legend: [],
    ex: "Breaking a promise to save more lives can be defended on consequentialist grounds, but condemned on deontological grounds if breaking promises is considered wrong regardless of outcome.",
    tip: "Apply several ethical perspectives to the same case — they often give different, complementary answers." } },
{ id: "fore-var-prinsippet",
  nb: { t: "Føre-var-prinsippet",
    intro: "Føre-var-prinsippet sier at mangel på full vitenskapelig sikkerhet ikke skal brukes som grunn til å utsette tiltak mot alvorlig eller irreversibel skade. Det brukes ofte i miljø- og helsespørsmål, der man ikke kan vente på hundre prosent bevis før man handler.",
    f: [["\\text{usikkerhet} \\neq \\text{grunn til å vente}", "føre-var-prinsippet ved alvorlig risiko"]],
    legend: [],
    ex: "Et nytt kjemikalie med mistenkt, men ikke fullt bevist, helserisiko kan likevel reguleres strengt før all forskning er ferdig.",
    tip: "Føre-var-prinsippet gjelder alvorlig eller irreversibel skade — det er ikke en generell unnskyldning for å unngå all risiko." },
  en: { t: "The precautionary principle",
    intro: "The precautionary principle states that lack of full scientific certainty should not be used as a reason to postpone action against serious or irreversible harm. It is often used in environmental and health questions, where one cannot wait for one hundred percent proof before acting.",
    f: [["\\text{uncertainty} \\neq \\text{reason to wait}", "the precautionary principle under serious risk"]],
    legend: [],
    ex: "A new chemical with suspected, but not fully proven, health risk can still be strictly regulated before all research is complete.",
    tip: "The precautionary principle applies to serious or irreversible harm — it is not a general excuse to avoid all risk." } },
{ id: "interessentanalyse-ansvarlig-innovasjon",
  nb: { t: "Interessenter og ansvarlig innovasjon",
    intro: "En interessentanalyse kartlegger hvem som påvirkes av eller kan påvirke et prosjekt, slik at alle berørte parter tas hensyn til tidlig. Ansvarlig innovasjon (RRI) betyr å ta hensyn til samfunnsmessige og etiske konsekvenser tidlig i utviklingen, ikke bare i etterkant.",
    f: [["\\text{kartlegg interessenter} \\to \\text{vurder konsekvenser tidlig}", "kjernen i ansvarlig innovasjon"]],
    legend: [],
    ex: "Ved utvikling av et overvåkingssystem bør både brukere, personvernorganisasjoner og de som overvåkes, identifiseres som interessenter tidlig i prosjektet.",
    tip: "Å vente med etiske vurderinger til produktet er ferdig, er for sent — de hører hjemme tidlig i prosessen." },
  en: { t: "Stakeholders and responsible innovation",
    intro: "A stakeholder analysis maps out who is affected by or can affect a project, so all affected parties are considered early. Responsible innovation (RRI) means considering societal and ethical consequences early in development, not just afterwards.",
    f: [["\\text{map stakeholders} \\to \\text{assess consequences early}", "the core of responsible innovation"]],
    legend: [],
    ex: "When developing a surveillance system, both users, privacy organizations, and those being monitored should be identified as stakeholders early in the project.",
    tip: "Waiting to consider ethics until the product is finished is too late — it belongs early in the process." } },
{ id: "personvern-samtykke",
  nb: { t: "Personvern, samtykke og GDPR",
    intro: "Informert samtykke betyr at personer får tilstrekkelig informasjon og frivillig sier ja før de deltar, sentralt både i forskning og i innsamling av persondata. GDPR bygger blant annet på dataminimering: man skal bare samle inn de personopplysningene man faktisk trenger, i tillegg til formåls- og lagringsbegrensning.",
    f: [["\\text{dataminimering} + \\text{formålsbegrensning} + \\text{lagringsbegrensning}", "sentrale GDPR-prinsipper"]],
    legend: [],
    ex: "En app som ber om tilgang til kontaktlisten uten at det trengs for appens funksjon, bryter med dataminimeringsprinsippet.",
    tip: "Samle bare inn det du faktisk trenger til det oppgitte formålet — «kan være nyttig senere» er ikke godt nok." },
  en: { t: "Privacy, consent and GDPR",
    intro: "Informed consent means people receive sufficient information and voluntarily agree before participating, central both in research and in personal data collection. GDPR is built partly on data minimization: only the personal data actually needed should be collected, alongside purpose and storage limitation.",
    f: [["\\text{data minimization} + \\text{purpose limitation} + \\text{storage limitation}", "key GDPR principles"]],
    legend: [],
    ex: "An app that requests access to the contact list without needing it for the app's function violates the data minimization principle.",
    tip: "Only collect what you actually need for the stated purpose — \"might be useful later\" is not good enough." } },
{ id: "varsling-interessekonflikt",
  nb: { t: "Varsling og interessekonflikt",
    intro: "Varsling i arbeidslivet betyr å si fra om kritikkverdige forhold, og arbeidsmiljøloven gir vern mot gjengjeldelse for den som varsler. En interessekonflikt oppstår når personlige interesser kan påvirke en faglig vurdering, og løses ofte ved å opplyse om den eller trekke seg fra saken (inhabilitet).",
    f: [["\\text{varsling: si fra} \\quad \\text{interessekonflikt: opplys eller trekk deg}", "to virkemidler for faglig integritet"]],
    legend: [],
    ex: "En ingeniør som skal vurdere et anbud fra et firma eid av en nær slektning, bør melde fra om interessekonflikten og la en annen ta avgjørelsen.",
    tip: "Etiske retningslinjer for ingeniører setter samfunnets sikkerhet, helse og velferd først — foran oppdragsgivers eller egen interesse." },
  en: { t: "Whistleblowing and conflict of interest",
    intro: "Whistleblowing in the workplace means reporting reprehensible conditions, and labour law protects whistleblowers from retaliation. A conflict of interest arises when personal interests could influence a professional judgment, and is often resolved by disclosing it or recusing oneself from the case.",
    f: [["\\text{whistleblowing: speak up} \\quad \\text{conflict of interest: disclose or recuse}", "two tools for professional integrity"]],
    legend: [],
    ex: "An engineer evaluating a bid from a company owned by a close relative should disclose the conflict of interest and let someone else make the decision.",
    tip: "Engineers' codes of ethics put society's safety, health and welfare first — ahead of the client's or one's own interest." } }
]);
// ---------------- MATS1500: Materialteknologi ----------------
TOPICS("MATS1500", 0, [
{ id: "krystallstrukturer",
  nb: { t: "Krystallstrukturer og pakningsgrad",
    intro: "De fleste metaller er krystallinske, med atomene ordnet i et regelmessig gitter. De vanligste strukturene er BCC (romsentrert kubisk, som jern ved romtemperatur), FCC (flatesentrert kubisk, som aluminium) og HCP (heksagonal tettpakket, som titan). Pakningsgraden (APF) sier hvor mye av volumet som er fylt av atomer.",
    f: [["\\text{APF} = \\frac{\\text{volum av atomer i cellen}}{\\text{volum av enhetscellen}}", "atompakningsgrad"]],
    legend: [["\\text{BCC}", "romsentrert kubisk, 2 atomer/celle, APF $= 0{,}68$", ""], ["\\text{FCC}", "flatesentrert kubisk, 4 atomer/celle, APF $= 0{,}74$", ""], ["\\text{HCP}", "heksagonal tettpakket, få glidesystemer", ""]],
    ex: "3 enhetsceller med FCC-struktur (4 atomer/celle) inneholder $3\\cdot 4 = 12$ atomer totalt.",
    tip: "FCC og HCP har høyest pakningsgrad ($0{,}74$), men FCC har flere glidesystemer og gir dermed bedre duktilitet." },
  en: { t: "Crystal structures and packing",
    intro: "Most metals are crystalline, with atoms arranged in a regular lattice. The most common structures are BCC (body-centered cubic, like iron at room temperature), FCC (face-centered cubic, like aluminum), and HCP (hexagonal close-packed, like titanium). The atomic packing factor (APF) shows how much of the volume is filled by atoms.",
    f: [["\\text{APF} = \\frac{\\text{volume of atoms in the cell}}{\\text{volume of the unit cell}}", "atomic packing factor"]],
    legend: [["\\text{BCC}", "body-centered cubic, 2 atoms/cell, APF $= 0.68$", ""], ["\\text{FCC}", "face-centered cubic, 4 atoms/cell, APF $= 0.74$", ""], ["\\text{HCP}", "hexagonal close-packed, few slip systems", ""]],
    ex: "3 unit cells of FCC structure (4 atoms/cell) contain $3\\cdot 4 = 12$ atoms in total.",
    tip: "FCC and HCP have the highest packing factor ($0.74$), but FCC has more slip systems and thus better ductility." } },
{ id: "korngrense-hall-petch",
  nb: { t: "Kornstørrelse og Hall–Petch",
    intro: "Metaller består av mange små krystaller (korn) med ulik orientering, adskilt av korngrenser. Korngrenser hindrer dislokasjoner i å bevege seg, så et finkornet materiale er sterkere enn et grovkornet av samme sammensetning. Dette kalles Hall–Petch-sammenhengen.",
    f: [["\\sigma_y = \\sigma_0 + \\frac{k}{\\sqrt{d}}", "Hall–Petch: flytegrense mot kornstørrelse"]],
    legend: [["\\sigma_y", "flytegrense", "MPa"], ["d", "gjennomsnittlig kornstørrelse", "µm"], ["\\sigma_0,\\ k", "materialkonstanter", ""]],
    ex: "Reduseres kornstørrelsen $d$, øker $1/\\sqrt d$ og dermed flytegrensen $\\sigma_y$.",
    tip: "Finkornet struktur gir høyere fasthet uten å endre legeringens sammensetning." },
  en: { t: "Grain size and Hall–Petch",
    intro: "Metals consist of many small crystals (grains) with different orientations, separated by grain boundaries. Grain boundaries hinder dislocation motion, so a fine-grained material is stronger than a coarse-grained one of the same composition. This is the Hall–Petch relationship.",
    f: [["\\sigma_y = \\sigma_0 + \\frac{k}{\\sqrt{d}}", "Hall–Petch: yield strength vs. grain size"]],
    legend: [["\\sigma_y", "yield strength", "MPa"], ["d", "average grain size", "µm"], ["\\sigma_0,\\ k", "material constants", ""]],
    ex: "Reducing the grain size $d$ increases $1/\\sqrt d$ and thus the yield strength $\\sigma_y$.",
    tip: "A fine-grained structure gives higher strength without changing the alloy's composition." } },
{ id: "defekter-dislokasjoner",
  nb: { t: "Defekter og dislokasjoner",
    intro: "Krystallgitre har alltid defekter. En vakans (tomt gitterpunkt) er en punktdefekt, mens en dislokasjon er en linjedefekt som gjør plastisk deformasjon mulig — når en dislokasjon vandrer gjennom gitteret, glir atomlagene litt i forhold til hverandre uten at hele planet må flytte seg på én gang.",
    f: [["\\text{vakans: punktdefekt} \\quad \\text{dislokasjon: linjedefekt}", "to grunnleggende defekttyper"]],
    legend: [],
    ex: "Arbeidsherding skjer fordi flere dislokasjoner dannes under deformasjon og begynner å hindre hverandre i å bevege seg videre.",
    tip: "Uten dislokasjoner ville metaller vært svært mye sterkere, men også umulige å forme plastisk." },
  en: { t: "Defects and dislocations",
    intro: "Crystal lattices always have defects. A vacancy (empty lattice site) is a point defect, while a dislocation is a line defect that makes plastic deformation possible — as a dislocation moves through the lattice, atomic layers slip slightly relative to each other without the whole plane having to move at once.",
    f: [["\\text{vacancy: point defect} \\quad \\text{dislocation: line defect}", "two basic defect types"]],
    legend: [],
    ex: "Work hardening occurs because more dislocations form during deformation and start blocking each other's further movement.",
    tip: "Without dislocations, metals would be far stronger, but also impossible to shape plastically." } },
{ id: "legeringer-fasediagram",
  nb: { t: "Legeringer og fasediagram",
    intro: "En legering er en blanding av et metall med andre grunnstoffer for å oppnå ønskede egenskaper, som karbonstål (jern og karbon) eller messing (kobber og sink). Et fasediagram viser hvilke faser som er stabile ved ulike temperaturer og sammensetninger, og brukes til å forstå og planlegge varmebehandling.",
    f: [["\\text{legering} = \\text{grunnmetall} + \\text{legeringselement(er)}", "definisjon av en legering"]],
    legend: [],
    ex: "Jern–karbon-diagrammet viser at selv under 2 % karbon i jern endrer stålets egenskaper dramatisk, fra mykt og duktilt til hardt og sprøtt.",
    tip: "Et fasediagram forteller hvilke faser som finnes ved likevekt — ikke hvor raskt de dannes ved avkjøling." },
  en: { t: "Alloys and phase diagrams",
    intro: "An alloy is a mixture of a metal with other elements to achieve desired properties, like carbon steel (iron and carbon) or brass (copper and zinc). A phase diagram shows which phases are stable at different temperatures and compositions, and is used to understand and plan heat treatment.",
    f: [["\\text{alloy} = \\text{base metal} + \\text{alloying element(s)}", "definition of an alloy"]],
    legend: [],
    ex: "The iron–carbon diagram shows that even under 2% carbon in iron dramatically changes the steel's properties, from soft and ductile to hard and brittle.",
    tip: "A phase diagram tells you which phases exist at equilibrium — not how fast they form on cooling." } }
]);
TOPICS("MATS1500", 1, [
{ id: "spenning-toyning",
  fig: `<svg viewBox="0 0 240 140"><path d="M30 120H220" class="dim"/><path d="M30 120V20" class="dim"/><path d="M30 120L90 55" class="d"/><path d="M90 55C 130 35, 160 30, 195 45" class="d"/><path d="M195 45L205 70" class="d"/><path d="M30 120H90V55" class="dash"/><text x="12" y="60">σ</text><text x="205" y="132">ε</text><text x="75" y="132">ε₀</text></svg>`,
  nb: { t: "Spenning–tøyning-kurve",
    intro: "Spenning–tøyning-kurven viser hvordan et materiale reagerer på last. I det elastiske området er spenning og tøyning proporsjonale via E-modulen. Flytegrensen ($R_e$ eller $R_{p0{,}2}$) markerer starten på plastisk deformasjon, og strekkfastheten $R_m$ er den høyeste spenningen kurven når.",
    f: [["\\sigma = \\frac{F}{A}", "spenning"], ["\\varepsilon = \\frac{\\Delta L}{L_0}", "tøyning"], ["E = \\frac{\\sigma}{\\varepsilon}", "E-modul (elastisk område)"]],
    legend: [["F", "kraft", "N"], ["A", "tverrsnittsareal", "mm²"], ["\\Delta L", "lengdeendring", "mm"], ["L_0", "opprinnelig lengde", "mm"]],
    ex: "Rund stav $d = 16$ mm, $F = 79$ kN: $A \\approx 201{,}1$ mm², $\\sigma = F/A \\approx 392{,}9$ MPa.\n$\\sigma = 40$ MPa, $\\varepsilon = 0{,}15$ %: $E = 40/0{,}0015 \\approx 26{,}7$ GPa.",
    tip: "$R_{p0{,}2}$ brukes når materialet ikke har en tydelig flytegrense — den er spenningen som gir 0,2 % varig tøyning." },
  en: { t: "Stress–strain curve",
    intro: "The stress–strain curve shows how a material responds to load. In the elastic region, stress and strain are proportional via the elastic modulus. The yield strength ($R_e$ or $R_{p0.2}$) marks the start of plastic deformation, and the tensile strength $R_m$ is the highest stress the curve reaches.",
    f: [["\\sigma = \\frac{F}{A}", "stress"], ["\\varepsilon = \\frac{\\Delta L}{L_0}", "strain"], ["E = \\frac{\\sigma}{\\varepsilon}", "elastic modulus (elastic region)"]],
    legend: [["F", "force", "N"], ["A", "cross-sectional area", "mm²"], ["\\Delta L", "change in length", "mm"], ["L_0", "original length", "mm"]],
    ex: "Round bar $d = 16$ mm, $F = 79$ kN: $A \\approx 201.1$ mm², $\\sigma = F/A \\approx 392.9$ MPa.\n$\\sigma = 40$ MPa, $\\varepsilon = 0.15\\%$: $E = 40/0.0015 \\approx 26.7$ GPa.",
    tip: "$R_{p0.2}$ is used when a material has no clear yield point — it is the stress giving 0.2% permanent strain." } },
{ id: "duktilitet-sprohet",
  nb: { t: "Duktilitet og sprøhet",
    intro: "Et duktilt materiale, som kobber eller konstruksjonsstål, deformeres plastisk mye før brudd, mens et sprøtt materiale, som glass eller støpejern, ryker med lite eller ingen plastisk deformasjon. Seighet (evnen til å absorbere energi før brudd) måles gjerne med en Charpy-slagprøve, der en pendel slår av en kjervet prøvestav.",
    f: [["\\text{duktilt: mye plastisk deformasjon} \\quad \\text{sprøtt: lite/ingen}", "hovedforskjellen før brudd"]],
    legend: [],
    ex: "Charpy-prøven måler slagenergien som går med til å bryte prøvestaven — lav energi tyder på sprøtt brudd, høy energi på duktilt.",
    tip: "Sprøhet øker ofte ved lav temperatur — mange stål har en sprø-duktil overgangstemperatur." },
  en: { t: "Ductility and brittleness",
    intro: "A ductile material, like copper or structural steel, deforms plastically a lot before fracture, while a brittle material, like glass or cast iron, breaks with little or no plastic deformation. Toughness (the ability to absorb energy before fracture) is often measured with a Charpy impact test, where a pendulum strikes a notched test bar.",
    f: [["\\text{ductile: much plastic deformation} \\quad \\text{brittle: little/none}", "the main difference before fracture"]],
    legend: [],
    ex: "The Charpy test measures the impact energy used to break the test bar — low energy suggests brittle fracture, high energy suggests ductile.",
    tip: "Brittleness often increases at low temperature — many steels have a ductile-to-brittle transition temperature." } },
{ id: "utmatting",
  nb: { t: "Utmatting og Wöhlerkurve",
    intro: "Utmattingsbrudd skjer ved varierende (syklisk) last, selv når spenningen holder seg under flytegrensen — sprekker vokser litt for hver lastsyklus til materialet til slutt ryker. En Wöhlerkurve (S–N-kurve) viser spenningsamplitude mot antall sykler til brudd, og mange stål har en utmattingsgrense der kurven flater ut.",
    f: [["\\text{S–N-kurve: } \\sigma_a \\text{ mot } N_f", "spenningsamplitude mot antall sykler til brudd"]],
    legend: [["\\sigma_a", "spenningsamplitude", "MPa"], ["N_f", "antall sykler til brudd", ""]],
    ex: "En komponent som tåler statisk last godt, kan likevel svikte etter millioner av lastsykler ved en spenning langt under flytegrensen.",
    tip: "Utmattingsgrensen finnes for mange stål, men sjelden for aluminium — der fortsetter fastheten å synke med flere sykler." },
  en: { t: "Fatigue and the S–N curve",
    intro: "Fatigue failure occurs under varying (cyclic) load, even when the stress stays below the yield strength — cracks grow a little with each load cycle until the material finally breaks. A Wöhler curve (S–N curve) plots stress amplitude against number of cycles to failure, and many steels have a fatigue limit where the curve flattens out.",
    f: [["\\text{S–N curve: } \\sigma_a \\text{ vs. } N_f", "stress amplitude against number of cycles to failure"]],
    legend: [["\\sigma_a", "stress amplitude", "MPa"], ["N_f", "number of cycles to failure", ""]],
    ex: "A component that easily withstands static load can still fail after millions of load cycles at a stress far below the yield strength.",
    tip: "A fatigue limit exists for many steels, but rarely for aluminum — there, strength keeps decreasing with more cycles." } },
{ id: "arbeidsherding",
  nb: { t: "Arbeidsherding (kaldforming)",
    intro: "Arbeidsherding er at plastisk deformasjon ved lav temperatur øker fastheten, fordi flere dislokasjoner dannes og begynner å hindre hverandre i å bevege seg. Effekten kan fjernes ved gløding, der oppvarming gir rekrystallisering og et mykere, mer duktilt materiale igjen.",
    f: [["\\text{plastisk deformasjon} \\to \\text{flere dislokasjoner} \\to \\text{høyere fasthet}", "mekanismen bak arbeidsherding"]],
    legend: [],
    ex: "En kobbertråd som bøyes fram og tilbake flere ganger, blir stivere og til slutt sprøere — den er arbeidsherdet.",
    tip: "Gløding «tilbakestiller» et arbeidsherdet materiale, men koster energi og en produksjonsoperasjon ekstra." },
  en: { t: "Work hardening (cold working)",
    intro: "Work hardening is that plastic deformation at low temperature increases strength, because more dislocations form and start blocking each other's movement. The effect can be removed by annealing, where heating causes recrystallization and gives back a softer, more ductile material.",
    f: [["\\text{plastic deformation} \\to \\text{more dislocations} \\to \\text{higher strength}", "the mechanism behind work hardening"]],
    legend: [],
    ex: "A copper wire bent back and forth several times becomes stiffer and eventually more brittle — it is work hardened.",
    tip: "Annealing \"resets\" a work-hardened material, but costs energy and an extra production step." } }
]);
TOPICS("MATS1500", 2, [
{ id: "herding-anlopning",
  nb: { t: "Herding og anløpning",
    intro: "Når stål bråkjøles (herdes) fra austenitt, dannes martensitt — en hard og sprø struktur fordi karbonet blir fanget i gitteret. Etterpå anløpes stålet ved moderat oppvarming, som gjør det mindre sprøtt med litt lavere hardhet, og gir et bedre kompromiss mellom seighet og hardhet.",
    f: [["\\text{austenitt} \\xrightarrow{\\text{bråkjøling}} \\text{martensitt} \\xrightarrow{\\text{anløpning}} \\text{seigere stål}", "herding og anløpning i to trinn"]],
    legend: [],
    ex: "Et bilverktøy herdes og anløpes for å balansere hardhet (slitestyrke) mot seighet (motstand mot sprøbrudd).",
    tip: "Herdet, men ikke anløpt, stål er ofte for sprøtt til praktisk bruk — anløpning er sjelden valgfritt." },
  en: { t: "Quenching and tempering",
    intro: "When steel is rapidly cooled (quenched) from austenite, martensite forms — a hard and brittle structure because the carbon gets trapped in the lattice. Afterwards the steel is tempered by moderate heating, which makes it less brittle with slightly lower hardness, giving a better compromise between toughness and hardness.",
    f: [["\\text{austenite} \\xrightarrow{\\text{quench}} \\text{martensite} \\xrightarrow{\\text{temper}} \\text{tougher steel}", "quenching and tempering in two steps"]],
    legend: [],
    ex: "A hand tool is quenched and tempered to balance hardness (wear resistance) against toughness (resistance to brittle fracture).",
    tip: "Quenched but untempered steel is often too brittle for practical use — tempering is rarely optional." } },
{ id: "normalisering-settherding",
  nb: { t: "Normalisering og settherding",
    intro: "Normalisering varmer stålet over austenittområdet og avkjøler det i luft, for å gi en finkornet og jevn struktur. Settherding (karburering) øker karboninnholdet i overflaten slik at den blir hard, mens kjernen forblir seig — mye brukt for tannhjul som trenger både slitestyrke og støtmotstand.",
    f: [["\\text{normalisering: finkornet, jevn struktur}", ""], ["\\text{settherding: hard overflate, seig kjerne}", ""]],
    legend: [],
    ex: "Et tannhjul settherdes slik at tennene tåler slitasje på overflaten, samtidig som kjernen tåler støt uten å knuse.",
    tip: "Legeringselementer som krom og molybden øker herdbarheten — hvor dypt stålet kan herdes ved bråkjøling." },
  en: { t: "Normalizing and carburizing",
    intro: "Normalizing heats the steel above the austenite range and cools it in air, giving a fine-grained and uniform structure. Carburizing (case hardening) increases the carbon content at the surface so it becomes hard while the core stays tough — widely used for gears that need both wear resistance and impact resistance.",
    f: [["\\text{normalizing: fine-grained, uniform structure}", ""], ["\\text{carburizing: hard surface, tough core}", ""]],
    legend: [],
    ex: "A gear is carburized so the teeth withstand surface wear while the core withstands impact without shattering.",
    tip: "Alloying elements like chromium and molybdenum increase hardenability — how deep steel can be hardened by quenching." } },
{ id: "korrosjon-galvanisk",
  nb: { t: "Galvanisk korrosjon og rustfritt stål",
    intro: "Når to ulike metaller er i kontakt i en elektrolytt, korroderer det minst edle (anoden), mens det mest edle (katoden) beskyttes — dette kalles galvanisk korrosjon, og utnyttes bevisst med offeranoder av sink på båter. Stål blir rustfritt med minst ca. 10,5 % krom, som danner et selvreparerende, passivt oksidsjikt (Cr₂O₃).",
    f: [["\\text{anode (uedel)}: \\text{korroderer} \\quad \\text{katode (edel)}: \\text{beskyttes}", "galvanisk korrosjon"]],
    legend: [],
    ex: "En sinkanode koblet til et stålskrog ofrer seg selv: sinken korroderer i stedet for stålet.",
    tip: "Unngå å koble svært ulike metaller direkte sammen i fuktige miljøer, med mindre den ene skal ofres bevisst." },
  en: { t: "Galvanic corrosion and stainless steel",
    intro: "When two different metals are in contact in an electrolyte, the less noble one (the anode) corrodes while the more noble one (the cathode) is protected — this is galvanic corrosion, deliberately used with sacrificial zinc anodes on boats. Steel becomes stainless with at least about 10.5% chromium, which forms a self-healing, passive oxide layer (Cr2O3).",
    f: [["\\text{anode (less noble)}: \\text{corrodes} \\quad \\text{cathode (more noble)}: \\text{protected}", "galvanic corrosion"]],
    legend: [],
    ex: "A zinc anode connected to a steel hull sacrifices itself: the zinc corrodes instead of the steel.",
    tip: "Avoid connecting very different metals directly in damp environments, unless one is meant to be sacrificed." } },
{ id: "kryp-glassovergang",
  nb: { t: "Kryp og glassovergangstemperatur",
    intro: "Kryp er tidsavhengig deformasjon under konstant last ved høy temperatur, viktig for eksempel i turbiner og kjeler. Glassovergangstemperaturen $T_g$ for en polymer er temperaturen der en amorf polymer går fra hard og glassaktig (og sprø) under $T_g$, til myk og gummiaktig over den.",
    f: [["\\text{kryp: tidsavhengig deformasjon ved konstant last, høy } T", ""], ["T < T_g: \\text{glassaktig, sprøtt} \\quad T > T_g: \\text{gummiaktig, mykt}", "polymerens tilstand rundt $T_g$"]],
    legend: [["T_g", "glassovergangstemperatur", "°C"]],
    ex: "En gummipakning som blir stiv og sprekker i sterk kulde, har sannsynligvis kommet under sin $T_g$.",
    tip: "Kryp blir betydelig først ved høy homolog temperatur (nær smeltepunktet), ikke ved romtemperatur for de fleste metaller." },
  en: { t: "Creep and glass transition",
    intro: "Creep is time-dependent deformation under constant load at high temperature, important for example in turbines and boilers. The glass transition temperature $T_g$ of a polymer is the temperature where an amorphous polymer goes from hard and glass-like (and brittle) below $T_g$, to soft and rubbery above it.",
    f: [["\\text{creep: time-dependent deformation at constant load, high } T", ""], ["T < T_g: \\text{glassy, brittle} \\quad T > T_g: \\text{rubbery, soft}", "the polymer's state around $T_g$"]],
    legend: [["T_g", "glass transition temperature", "°C"]],
    ex: "A rubber gasket that becomes stiff and cracks in severe cold has likely dropped below its $T_g$.",
    tip: "Creep only becomes significant at a high homologous temperature (near the melting point), not at room temperature for most metals." } },
{ id: "termisk-ekspansjon",
  nb: { t: "Termisk ekspansjon",
    intro: "De fleste materialer utvider seg når temperaturen øker. Lengdeutvidelsen er tilnærmet proporsjonal med opprinnelig lengde, temperaturendringen og materialets lineære utvidelseskoeffisient $\\alpha$. Dette må tas hensyn til i konstruksjoner med store temperatursvingninger, som broer og rørledninger.",
    f: [["\\Delta L = \\alpha\\, L_0\\, \\Delta T", "lengdeøkning ved temperaturendring"]],
    legend: [["\\alpha", "lineær utvidelseskoeffisient", "1/K"], ["L_0", "opprinnelig lengde", "m"], ["\\Delta T", "temperaturøkning", "K"]],
    ex: "Kobberskinne 3 m, $\\alpha = 17\\cdot 10^{-6}$/K, oppvarming 75 K:\n$\\Delta L = 17\\cdot10^{-6}\\cdot 3\\cdot 75 \\approx 3{,}825$ mm.",
    tip: "Ekspansjonsfuger i broer og rør finnes nettopp for å håndtere denne lengdeendringen uten å bygge opp spenning." },
  en: { t: "Thermal expansion",
    intro: "Most materials expand when temperature increases. The length increase is approximately proportional to the original length, the temperature change, and the material's linear expansion coefficient $\\alpha$. This must be accounted for in structures with large temperature swings, like bridges and pipelines.",
    f: [["\\Delta L = \\alpha\\, L_0\\, \\Delta T", "length increase with temperature change"]],
    legend: [["\\alpha", "linear expansion coefficient", "1/K"], ["L_0", "original length", "m"], ["\\Delta T", "temperature increase", "K"]],
    ex: "Copper busbar 3 m, $\\alpha = 17\\times 10^{-6}$/K, heated 75 K:\n$\\Delta L = 17\\times10^{-6}\\cdot 3\\cdot 75 \\approx 3.825$ mm.",
    tip: "Expansion joints in bridges and pipes exist precisely to handle this length change without building up stress." } }
]);
