TOPICS("KJEMI", 0, [
{ id: "mol-og-molar-masse",
  nb: { t: "Mol og molar masse",
    intro: "Mol er den kjemiske enheten for mengde stoff: én mol inneholder Avogadros tall, $6{,}022\\cdot10^{23}$, partikler. Molar masse er massen av én mol av et stoff, i g/mol, og finnes ved å summere atommassene fra periodesystemet. Sammen lar de deg gå mellom antall mol og masse i gram.",
    f: [["n = \\frac{m}{M}", "antall mol fra masse og molar masse"], ["N = n\\cdot N_A", "antall partikler, $N_A = 6{,}022\\cdot10^{23}$/mol"]],
    legend: [["n", "antall mol", "mol"], ["m", "masse", "g"], ["M", "molar masse", "g/mol"], ["N_A", "Avogadros tall", "1/mol"]],
    ex: "180 g CO₂, $M = 44{,}01$ g/mol:\n$n = 180/44{,}01 \\approx 4{,}09$ mol.",
    tip: "Molar masse har alltid enheten g/mol — bland den ikke sammen med atommassen i u (som er tallverdimessig lik)." },
  en: { t: "Moles and molar mass",
    intro: "The mole is the chemical unit for amount of substance: one mole contains Avogadro's number, $6.022\\times10^{23}$, particles. Molar mass is the mass of one mole of a substance, in g/mol, found by summing atomic masses from the periodic table. Together they let you convert between number of moles and mass in grams.",
    f: [["n = \\frac{m}{M}", "number of moles from mass and molar mass"], ["N = n\\cdot N_A", "number of particles, $N_A = 6.022\\times10^{23}$/mol"]],
    legend: [["n", "amount of substance", "mol"], ["m", "mass", "g"], ["M", "molar mass", "g/mol"], ["N_A", "Avogadro's number", "1/mol"]],
    ex: "180 g CO2, $M = 44.01$ g/mol:\n$n = 180/44.01 \\approx 4.09$ mol.",
    tip: "Molar mass always has the unit g/mol — do not confuse it with atomic mass in u (which is numerically equal)." } },
{ id: "konsentrasjon-fortynning",
  nb: { t: "Konsentrasjon og fortynning",
    intro: "Molaritet (konsentrasjon) er antall mol stoff per liter løsning, med enheten mol/L, ofte skrevet M. Fortynnes en løsning, endres volumet, men antall mol stoff er uendret — det gir en enkel sammenheng mellom konsentrasjon og volum før og etter fortynning.",
    f: [["c = \\frac{n}{V}", "konsentrasjon (molaritet)"], ["c_1V_1 = c_2V_2", "fortynningsligningen (samme antall mol)"]],
    legend: [["c", "konsentrasjon", "mol/L"], ["n", "antall mol", "mol"], ["V", "volum løsning", "L"]],
    ex: "10 mL av 1 M løsning fortynnes til 1000 mL:\n$c_2 = c_1V_1/V_2 = 1\\cdot 10/1000 = 0{,}01$ M.",
    tip: "Bruk samme volumenhet på begge sider av $c_1V_1 = c_2V_2$ — den trenger ikke være liter, bare konsekvent." },
  en: { t: "Concentration and dilution",
    intro: "Molarity (concentration) is the number of moles of substance per liter of solution, with the unit mol/L, often written M. When a solution is diluted, the volume changes but the number of moles of substance stays the same — giving a simple relationship between concentration and volume before and after dilution.",
    f: [["c = \\frac{n}{V}", "concentration (molarity)"], ["c_1V_1 = c_2V_2", "the dilution equation (same number of moles)"]],
    legend: [["c", "concentration", "mol/L"], ["n", "amount of substance", "mol"], ["V", "volume of solution", "L"]],
    ex: "10 mL of a 1 M solution diluted to 1000 mL:\n$c_2 = c_1V_1/V_2 = 1\\cdot 10/1000 = 0.01$ M.",
    tip: "Use the same volume unit on both sides of $c_1V_1 = c_2V_2$ — it does not need to be liters, just consistent." } },
{ id: "balansert-ligning-begrensende",
  nb: { t: "Begrensende reaktant",
    intro: "En kjemisk ligning er balansert når det er like mange atomer av hvert grunnstoff på begge sider. Reagerer to eller flere stoffer, er den begrensende reaktanten den som brukes opp først og dermed bestemmer hvor mye produkt som kan dannes — den finnes ved å regne om til mol og sammenligne med koeffisientene i den balanserte ligningen.",
    f: [["\\mathrm{CH_4 + 2O_2 \\to CO_2 + 2H_2O}", "eksempel på balansert ligning: C, H og O stemmer på begge sider"]],
    legend: [],
    ex: "32 g CH₄ ($M = 16{,}04$) gir $n = 1{,}995$ mol, som gir like mange mol CO₂ ($M = 44{,}01$):\n$1{,}995\\cdot 44{,}01 \\approx 87{,}8$ g CO₂.",
    tip: "Sammenlign alltid mol, ikke gram, når du finner den begrensende reaktanten — koeffisientene i ligningen gjelder mol." },
  en: { t: "Balanced equations and limiting reactant",
    intro: "A chemical equation is balanced when there are equally many atoms of each element on both sides. When two or more substances react, the limiting reactant is the one used up first and thus determines how much product can form — found by converting to moles and comparing with the coefficients in the balanced equation.",
    f: [["\\mathrm{CH_4 + 2O_2 \\to CO_2 + 2H_2O}", "example of a balanced equation: C, H and O match on both sides"]],
    legend: [],
    ex: "32 g CH4 ($M = 16.04$) gives $n = 1.995$ mol, giving the same number of moles of CO2 ($M = 44.01$):\n$1.995\\cdot 44.01 \\approx 87.8$ g CO2.",
    tip: "Always compare moles, not grams, when finding the limiting reactant — the equation's coefficients apply to moles." } },
{ id: "utbytteprosent",
  nb: { t: "Utbytteprosent",
    intro: "Utbytteprosent viser hvor mye produkt som faktisk dannes i en reaksjon, sammenlignet med det teoretiske maksimum beregnet fra støkiometrien. Den er sjelden 100 % i praksis, på grunn av sidereaksjoner, ufullstendig reaksjon eller tap ved rensing.",
    f: [["\\text{utbytte} = \\frac{\\text{faktisk mengde}}{\\text{teoretisk mengde}}\\times 100\\%", "utbytteprosent"]],
    legend: [],
    ex: "Teoretisk 87,8 g CO₂ forventet, men bare 80 g dannes:\nUtbytte $= (80/87{,}8)\\times 100 \\approx 91$ %.",
    tip: "Regn alltid ut det teoretiske utbyttet fra den begrensende reaktanten, ikke fra et overskuddsreagens." },
  en: { t: "Percent yield",
    intro: "Percent yield shows how much product actually forms in a reaction, compared to the theoretical maximum calculated from stoichiometry. It is rarely 100% in practice, due to side reactions, incomplete reaction, or losses during purification.",
    f: [["\\text{yield} = \\frac{\\text{actual amount}}{\\text{theoretical amount}}\\times 100\\%", "percent yield"]],
    legend: [],
    ex: "Theoretical 87.8 g CO2 expected, but only 80 g forms:\nYield $= (80/87.8)\\times 100 \\approx 91\\%$.",
    tip: "Always calculate the theoretical yield from the limiting reactant, not from a reagent in excess." } }
]);
TOPICS("KJEMI", 1, [
{ id: "ph-skala",
  nb: { t: "pH-skalaen",
    intro: "pH måler surhetsgraden til en løsning ut fra konsentrasjonen av $\\mathrm{H^+}$-ioner: lav pH betyr sur løsning, høy pH betyr basisk. Ved 25 °C er summen av pH og pOH alltid 14, siden vannets ioneprodukt $K_w = 10^{-14}$.",
    f: [["\\mathrm{pH} = -\\log[\\mathrm{H^+}]", "definisjon av pH"], ["\\mathrm{pH} + \\mathrm{pOH} = 14", "ved 25 °C"]],
    legend: [["[\\mathrm{H^+}]", "konsentrasjon av hydrogenioner", "mol/L"]],
    ex: "En løsning har pH 3, nøytralt vann har pH 7:\n$[\\mathrm{H^+}]$ er $10^{7-3} = 10\\,000$ ganger høyere.",
    tip: "pH-skalaen er logaritmisk: hver enhet ned betyr ti ganger høyere $\\mathrm{H^+}$-konsentrasjon." },
  en: { t: "The pH scale",
    intro: "pH measures the acidity of a solution from the concentration of $\\mathrm{H^+}$ ions: low pH means an acidic solution, high pH means basic. At 25 °C, the sum of pH and pOH is always 14, since water's ion product $K_w = 10^{-14}$.",
    f: [["\\mathrm{pH} = -\\log[\\mathrm{H^+}]", "definition of pH"], ["\\mathrm{pH} + \\mathrm{pOH} = 14", "at 25 °C"]],
    legend: [["[\\mathrm{H^+}]", "hydrogen ion concentration", "mol/L"]],
    ex: "A solution has pH 3, neutral water has pH 7:\n$[\\mathrm{H^+}]$ is $10^{7-3} = 10{,}000$ times higher.",
    tip: "The pH scale is logarithmic: each unit down means ten times higher $\\mathrm{H^+}$ concentration." } },
{ id: "sterk-svak-syre",
  nb: { t: "Sterke og svake syrer",
    intro: "En sterk syre, som HCl eller HNO₃, protolyserer (dissosierer) fullstendig i vann, så $[\\mathrm{H^+}]$ er lik den oppgitte konsentrasjonen. En svak syre dissosierer bare delvis, og gir dermed en lavere $[\\mathrm{H^+}]$ og høyere pH enn en sterk syre med samme konsentrasjon.",
    f: [["[\\mathrm{H^+}] = c \\ \\text{(sterk syre, fullstendig dissosiert)}", "for en sterk syre med konsentrasjon $c$"]],
    legend: [["c", "oppgitt (total) konsentrasjon av syren", "mol/L"]],
    ex: "0,05 M HCl (sterk syre): $[\\mathrm{H^+}] = 0{,}05$, $\\mathrm{pH} = -\\log(0{,}05) \\approx 1{,}3$.",
    tip: "For sterke syrer og baser kan du sette $[\\mathrm{H^+}]$ eller $[\\mathrm{OH^-}]$ lik konsentrasjonen direkte — det gjelder ikke for svake." },
  en: { t: "Strong and weak acids",
    intro: "A strong acid, like HCl or HNO3, protolyzes (dissociates) completely in water, so $[\\mathrm{H^+}]$ equals the stated concentration. A weak acid only partially dissociates, giving a lower $[\\mathrm{H^+}]$ and higher pH than a strong acid at the same concentration.",
    f: [["[\\mathrm{H^+}] = c \\ \\text{(strong acid, fully dissociated)}", "for a strong acid of concentration $c$"]],
    legend: [["c", "stated (total) concentration of the acid", "mol/L"]],
    ex: "0.05 M HCl (strong acid): $[\\mathrm{H^+}] = 0.05$, $\\mathrm{pH} = -\\log(0.05) \\approx 1.3$.",
    tip: "For strong acids and bases you can set $[\\mathrm{H^+}]$ or $[\\mathrm{OH^-}]$ equal to the concentration directly — this does not hold for weak ones." } },
{ id: "buffer",
  nb: { t: "Buffer",
    intro: "En buffer er en løsning av en svak syre og dens korresponderende base (eller en svak base og dens korresponderende syre), som motstår store endringer i pH når det tilsettes litt syre eller base. Blodet er for eksempel bufret rundt pH 7,4, noe som er avgjørende for at cellene skal fungere.",
    f: [["\\text{buffer} = \\text{svak syre} + \\text{korresponderende base}", "sammensetningen av en buffer"]],
    legend: [],
    ex: "En blanding av eddiksyre og natriumacetat holder pH nesten uendret selv om man tilsetter en liten mengde sterk syre eller base.",
    tip: "Bufferkapasiteten er størst når mengdene av syre og korresponderende base er omtrent like store." },
  en: { t: "Buffer",
    intro: "A buffer is a solution of a weak acid and its conjugate base (or a weak base and its conjugate acid), which resists large changes in pH when a little acid or base is added. Blood, for example, is buffered around pH 7.4, which is essential for cells to function.",
    f: [["\\text{buffer} = \\text{weak acid} + \\text{conjugate base}", "the composition of a buffer"]],
    legend: [],
    ex: "A mixture of acetic acid and sodium acetate keeps pH nearly unchanged even if a small amount of strong acid or base is added.",
    tip: "Buffer capacity is greatest when the amounts of acid and conjugate base are roughly equal." } },
{ id: "le-chateliers-prinsipp",
  nb: { t: "Le Châteliers prinsipp",
    intro: "Le Châteliers prinsipp sier at en kjemisk likevekt forskyves slik at den motvirker en ytre endring, som endret konsentrasjon, trykk eller temperatur. Økt trykk favoriserer for eksempel siden av reaksjonen med færrest gassmolekyler, siden det reduserer det totale volumet.",
    f: [["\\text{ytre endring} \\to \\text{likevekten forskyves for å motvirke den}", "Le Châteliers prinsipp"]],
    legend: [],
    ex: "Fjernes produktet kontinuerlig fra en reversibel reaksjon, forskyves likevekten mot mer produktdannelse for å erstatte det som fjernes.",
    tip: "En katalysator endrer ikke likevekten selv, bare hvor raskt den nås — Le Châteliers prinsipp handler om selve likevektsposisjonen." },
  en: { t: "Le Chatelier's principle",
    intro: "Le Chatelier's principle states that a chemical equilibrium shifts to counteract an external change, such as altered concentration, pressure, or temperature. Increased pressure, for example, favors the side of the reaction with fewer gas molecules, since it reduces the total volume.",
    f: [["\\text{external change} \\to \\text{equilibrium shifts to counteract it}", "Le Chatelier's principle"]],
    legend: [],
    ex: "If product is continuously removed from a reversible reaction, the equilibrium shifts toward more product formation to replace what is removed.",
    tip: "A catalyst does not change the equilibrium itself, only how fast it is reached — Le Chatelier's principle concerns the equilibrium position." } }
]);
TOPICS("KJEMI", 2, [
{ id: "entalpi-eksoterm",
  nb: { t: "Entalpi og eksoterme reaksjoner",
    intro: "Reaksjonsentalpien $\\Delta H$ viser om en reaksjon avgir eller tar opp varme ved konstant trykk. En eksoterm reaksjon avgir varme til omgivelsene og har $\\Delta H < 0$, som forbrenning, mens en endoterm reaksjon tar opp varme og har $\\Delta H > 0$.",
    f: [["\\Delta H < 0", "eksoterm: reaksjonen avgir varme"], ["\\Delta H > 0", "endoterm: reaksjonen tar opp varme"]],
    legend: [["\\Delta H", "reaksjonsentalpi", "kJ/mol"]],
    ex: "Forbrenning av metan avgir varme til omgivelsene: reaksjonen er eksoterm med $\\Delta H < 0$.",
    tip: "Eksoterme reaksjoner kan gå trått uten varmetilførsel — fortegnet på $\\Delta H$ sier ingenting om reaksjonsfarten." },
  en: { t: "Enthalpy and exothermic reactions",
    intro: "The reaction enthalpy $\\Delta H$ shows whether a reaction releases or absorbs heat at constant pressure. An exothermic reaction releases heat to the surroundings and has $\\Delta H < 0$, like combustion, while an endothermic reaction absorbs heat and has $\\Delta H > 0$.",
    f: [["\\Delta H < 0", "exothermic: the reaction releases heat"], ["\\Delta H > 0", "endothermic: the reaction absorbs heat"]],
    legend: [["\\Delta H", "reaction enthalpy", "kJ/mol"]],
    ex: "Combustion of methane releases heat to the surroundings: the reaction is exothermic with $\\Delta H < 0$.",
    tip: "Exothermic reactions can still proceed slowly without heat input — the sign of $\\Delta H$ says nothing about reaction rate." } },
{ id: "gibbs-fri-energi",
  nb: { t: "Gibbs frie energi og spontanitet",
    intro: "Gibbs frie energi $\\Delta G$ avgjør om en reaksjon er spontan ved konstant temperatur og trykk: er $\\Delta G < 0$, går reaksjonen av seg selv i den retningen. Den kombinerer entalpi (varmeeffekt) og entropi (uorden) via temperaturen. Spontan betyr ikke nødvendigvis rask.",
    f: [["\\Delta G = \\Delta H - T\\Delta S", "Gibbs frie energi"], ["\\Delta G < 0", "spontan reaksjon"]],
    legend: [["\\Delta H", "reaksjonsentalpi", "kJ/mol"], ["\\Delta S", "entropiendring", "kJ/(mol·K)"], ["T", "absolutt temperatur", "K"]],
    ex: "$\\Delta H = 50$ kJ/mol, $\\Delta S = 0{,}05$ kJ/(mol·K), $T = 250$ K:\n$\\Delta G = 50 - 250\\cdot 0{,}05 = 37{,}5$ kJ/mol $> 0$ — ikke spontan.",
    tip: "En reaksjon med $\\Delta H > 0$ kan likevel bli spontan ved høy nok temperatur, hvis $\\Delta S > 0$." },
  en: { t: "Gibbs free energy and spontaneity",
    intro: "Gibbs free energy $\\Delta G$ determines whether a reaction is spontaneous at constant temperature and pressure: if $\\Delta G < 0$, the reaction proceeds on its own in that direction. It combines enthalpy (heat effect) and entropy (disorder) via temperature. Spontaneous does not necessarily mean fast.",
    f: [["\\Delta G = \\Delta H - T\\Delta S", "Gibbs free energy"], ["\\Delta G < 0", "spontaneous reaction"]],
    legend: [["\\Delta H", "reaction enthalpy", "kJ/mol"], ["\\Delta S", "entropy change", "kJ/(mol·K)"], ["T", "absolute temperature", "K"]],
    ex: "$\\Delta H = 50$ kJ/mol, $\\Delta S = 0.05$ kJ/(mol·K), $T = 250$ K:\n$\\Delta G = 50 - 250\\cdot 0.05 = 37.5$ kJ/mol $> 0$ — not spontaneous.",
    tip: "A reaction with $\\Delta H > 0$ can still become spontaneous at a high enough temperature, if $\\Delta S > 0$." } },
{ id: "redoks-elektronegativitet",
  nb: { t: "Redoksreaksjoner og elektronegativitet",
    intro: "Oksidasjon er avgivelse av elektroner, reduksjon er opptak av elektroner — huskeregelen er OIL RIG. Elektronegativitet er et atoms evne til å trekke elektroner til seg i en binding; fluor har høyest elektronegativitet. Stor forskjell i elektronegativitet gir ionebinding, liten forskjell gir kovalent binding.",
    f: [["\\text{OIL RIG: Oxidation Is Loss, Reduction Is Gain}", "huskeregel for elektronoverføring"]],
    legend: [],
    ex: "I reaksjonen $\\mathrm{Zn + Cu^{2+} \\to Zn^{2+} + Cu}$ oksideres sink (avgir elektroner) og kobberionet reduseres (tar opp elektroner).",
    tip: "Sink brukes som offeranode for å beskytte stål i sjøvann fordi det er mindre edelt og oksideres i stedet for stålet." },
  en: { t: "Redox reactions and electronegativity",
    intro: "Oxidation is the loss of electrons, reduction is the gain of electrons — the mnemonic is OIL RIG. Electronegativity is an atom's ability to attract electrons in a bond; fluorine has the highest electronegativity. A large electronegativity difference gives an ionic bond, a small difference gives a covalent bond.",
    f: [["\\text{OIL RIG: Oxidation Is Loss, Reduction Is Gain}", "mnemonic for electron transfer"]],
    legend: [],
    ex: "In the reaction $\\mathrm{Zn + Cu^{2+} \\to Zn^{2+} + Cu}$, zinc is oxidized (loses electrons) and the copper ion is reduced (gains electrons).",
    tip: "Zinc is used as a sacrificial anode to protect steel in seawater because it is less noble and oxidizes instead of the steel." } },
{ id: "elektrolyse-faraday",
  nb: { t: "Elektrolyse og Faradays lov",
    intro: "I en galvanisk celle gir en spontan redoksreaksjon elektrisk strøm, som i et batteri. I elektrolyse går det motsatt vei: elektrisk strøm driver en ikke-spontan redoksreaksjon. Faradays lov knytter massen som felles ut ved en elektrode til strømmen, tiden og antall elektroner som overføres per ion.",
    f: [["m = \\frac{I\\,t\\,M}{z\\,F}", "masse felt ut ved elektrolyse"]],
    legend: [["I", "strøm", "A"], ["t", "tid", "s"], ["M", "molar masse av stoffet", "g/mol"], ["z", "antall elektroner overført per ion", ""], ["F", "Faradays konstant, $96\\,485$ C/mol", ""]],
    ex: "10 A i 10 min ($t=600$ s) på Ag⁺ ($M = 107{,}87$, $z=1$):\n$m = \\dfrac{10\\cdot 600\\cdot 107{,}87}{1\\cdot 96\\,485} \\approx 6{,}71$ g.",
    tip: "Husk å regne om tiden til sekunder — Faradays konstant er definert per sekund via ampere." },
  en: { t: "Electrolysis and Faraday's law",
    intro: "In a galvanic cell, a spontaneous redox reaction produces electric current, as in a battery. In electrolysis it goes the other way: electric current drives a non-spontaneous redox reaction. Faraday's law relates the mass deposited at an electrode to the current, time, and number of electrons transferred per ion.",
    f: [["m = \\frac{I\\,t\\,M}{z\\,F}", "mass deposited during electrolysis"]],
    legend: [["I", "current", "A"], ["t", "time", "s"], ["M", "molar mass of the substance", "g/mol"], ["z", "number of electrons transferred per ion", ""], ["F", "Faraday's constant, $96{,}485$ C/mol", ""]],
    ex: "10 A for 10 min ($t=600$ s) on Ag+ ($M = 107.87$, $z=1$):\n$m = \\dfrac{10\\cdot 600\\cdot 107.87}{1\\cdot 96{,}485} \\approx 6.71$ g.",
    tip: "Remember to convert time to seconds — Faraday's constant is defined per second via amperes." } },
{ id: "ideell-gasslov",
  nb: { t: "Ideell gasslov",
    intro: "Den ideelle gassloven knytter sammen trykk, volum, mengde og temperatur for en gass som oppfører seg ideelt. Den brukes til å regne ut volum, trykk eller mengde gass når de andre størrelsene er kjent.",
    f: [["pV = nRT", "ideell gasslov"]],
    legend: [["p", "trykk", "kPa"], ["V", "volum", "L"], ["n", "antall mol gass", "mol"], ["R", "gasskonstanten, $8{,}314$ J/(mol·K)", ""], ["T", "absolutt temperatur", "K"]],
    ex: "1 mol gass ved 373 K og 100 kPa:\n$V = nRT/p = 1\\cdot 8{,}314\\cdot 373/100 \\approx 31{,}01$ L.",
    tip: "Bruk konsekvente enheter (kPa og L, eller Pa og m³) — gasskonstanten $R$ finnes i flere varianter avhengig av enhetsvalg." },
  en: { t: "Ideal gas law",
    intro: "The ideal gas law relates pressure, volume, amount, and temperature for a gas that behaves ideally. It is used to calculate volume, pressure, or amount of gas when the other quantities are known.",
    f: [["pV = nRT", "ideal gas law"]],
    legend: [["p", "pressure", "kPa"], ["V", "volume", "L"], ["n", "amount of gas", "mol"], ["R", "gas constant, $8.314$ J/(mol·K)", ""], ["T", "absolute temperature", "K"]],
    ex: "1 mol of gas at 373 K and 100 kPa:\n$V = nRT/p = 1\\cdot 8.314\\cdot 373/100 \\approx 31.01$ L.",
    tip: "Use consistent units (kPa and L, or Pa and m³) — the gas constant $R$ comes in several forms depending on unit choice." } }
]);
TOPICS("MEK1300", 2, [
{ id: "funksjoner",
  nb: { t: "Funksjoner og return",
    intro: "En funksjon defineres med `def` og kan ta imot parametre, gjerne med standardverdier. `return` avslutter funksjonen og sender en verdi tilbake til kallstedet. Uten `return` gir funksjonen `None`.",
    f: [["\\text{def } f(a, b{=}c): \\ldots \\text{return } e", "$f$ returnerer verdien av $e$; $b$ får standardverdi $c$ hvis den ikke gis"]],
    legend: [["a,\\ b", "parametre", ""], ["c", "standardverdi for $b$", ""], ["e", "uttrykket som returneres", ""]],
    ex: "`def f(a, b=2): return a * b`\n`f(3)` bruker standardverdien: $3\\cdot 2 = 6$.",
    tip: "En funksjon uten `return`-setning gir alltid `None`, ikke 0 eller tom streng." },
  en: { t: "Functions and return",
    intro: "A function is defined with `def` and can take parameters, often with default values. `return` ends the function and sends a value back to the caller. Without `return`, the function gives `None`.",
    f: [["\\text{def } f(a, b{=}c): \\ldots \\text{return } e", "$f$ returns the value of $e$; $b$ gets default $c$ if not supplied"]],
    legend: [["a,\\ b", "parameters", ""], ["c", "default value for $b$", ""], ["e", "the expression returned", ""]],
    ex: "`def f(a, b=2): return a * b`\n`f(3)` uses the default: $3\\cdot 2 = 6$.",
    tip: "A function with no `return` statement always gives `None`, not 0 or an empty string." } },
{ id: "ordbok",
  nb: { t: "Ordbok (dict)",
    intro: "En ordbok, `{\"a\": 1}`, lagrer par av nøkkel og verdi. Du henter en verdi med `d[nøkkel]` eller trygt med `d.get(nøkkel, standard)`, som ikke gir feil om nøkkelen mangler. Å tilordne en ny nøkkel legger den til.",
    f: [["d[k]", "verdien til nøkkelen $k$"], ["d.\\text{get}(k, v_0)", "verdien til $k$, eller $v_0$ hvis $k$ mangler"]],
    legend: [["d", "en ordbok", ""], ["k", "en nøkkel", ""], ["v_0", "standardverdi", ""]],
    ex: "`d = {\"a\": 2, \"b\": 7}`\n`d.get(\"c\", 3)` gir `3`, siden `\"c\"` ikke finnes i `d`.",
    tip: "`d[k]` gir `KeyError` hvis nøkkelen mangler — bruk `.get` når du er usikker." },
  en: { t: "Dictionary (dict)",
    intro: "A dictionary, `{\"a\": 1}`, stores key–value pairs. You get a value with `d[key]` or safely with `d.get(key, default)`, which does not error if the key is missing. Assigning a new key adds it.",
    f: [["d[k]", "the value for key $k$"], ["d.\\text{get}(k, v_0)", "the value for $k$, or $v_0$ if $k$ is missing"]],
    legend: [["d", "a dictionary", ""], ["k", "a key", ""], ["v_0", "default value", ""]],
    ex: "`d = {\"a\": 2, \"b\": 7}`\n`d.get(\"c\", 3)` gives `3`, since `\"c\"` is not in `d`.",
    tip: "`d[k]` raises `KeyError` if the key is missing — use `.get` when unsure." } },
{ id: "strengmetoder",
  nb: { t: "Strengmetoder",
    intro: "Strenger har innebygde metoder som `.upper()`, `.split(sep)` og `.count(sub)`. `split` deler en streng ved et skilletegn og gir en liste av delstrenger. Metoder returnerer alltid en ny verdi og endrer ikke originalstrengen.",
    f: [["s.\\text{split}(c)", "deler $s$ ved tegnet $c$, gir en liste"], ["s.\\text{count}(t)", "antall ganger $t$ forekommer i $s$"]],
    legend: [["s", "en streng", ""], ["c", "skilletegn", ""], ["t", "delstrengen som telles", ""]],
    ex: "`\"a,b,c\".split(\",\")` gir `['a', 'b', 'c']`.\n`\"termo\".count(\"m\")` gir `1`.",
    tip: "Strenger er immutable: `s.upper()` lager en ny streng, den endrer ikke `s`." },
  en: { t: "String methods",
    intro: "Strings have built-in methods like `.upper()`, `.split(sep)` and `.count(sub)`. `split` divides a string at a separator and returns a list of substrings. Methods always return a new value and never change the original string.",
    f: [["s.\\text{split}(c)", "splits $s$ at character $c$, gives a list"], ["s.\\text{count}(t)", "number of times $t$ occurs in $s$"]],
    legend: [["s", "a string", ""], ["c", "separator", ""], ["t", "the substring counted", ""]],
    ex: "`\"a,b,c\".split(\",\")` gives `['a', 'b', 'c']`.\n`\"termo\".count(\"m\")` gives `1`.",
    tip: "Strings are immutable: `s.upper()` creates a new string, it does not change `s`." } },
{ id: "mutable-referanser",
  nb: { t: "Mutable objekter og referanser",
    intro: "Lister og ordbøker er mutable: sendes de inn i en funksjon, jobber funksjonen på den samme, delte lista — endringer ser man også utenfor. Tall, strenger og tupler er immutable og kan aldri endres i etterkant, bare erstattes.",
    f: [["f(x) \\Rightarrow x \\text{ endres varig, hvis } x \\text{ er mutable}", "f.eks. `list.append`"]],
    legend: [["x", "objektet som sendes til funksjonen", ""]],
    ex: "`def f(x): x.append(4)`\n`a = [1, 2, 3]`; `f(a)`\n`len(a)` er nå `4`, fordi `a` og `x` peker på samme liste.",
    tip: "Vil du beholde originalen uendret, send en kopi: `f(a.copy())`." },
  en: { t: "Mutable objects and references",
    intro: "Lists and dictionaries are mutable: when passed into a function, the function works on the same, shared list — changes are visible outside too. Numbers, strings and tuples are immutable and can never be changed afterwards, only replaced.",
    f: [["f(x) \\Rightarrow x \\text{ changes permanently, if } x \\text{ is mutable}", "e.g. `list.append`"]],
    legend: [["x", "the object passed to the function", ""]],
    ex: "`def f(x): x.append(4)`\n`a = [1, 2, 3]`; `f(a)`\n`len(a)` is now `4`, because `a` and `x` point to the same list.",
    tip: "To keep the original unchanged, pass a copy: `f(a.copy())`." } }
]);
